import { useEffect, useMemo, useRef, useState } from "react";
import { Project, Settings } from "@/api/gatedEntities";
import { Link, useNavigate, useSearchParams } from "react-router-dom";
import { AlertTriangle, ArrowLeft, Palette, Plus, Save, Trash2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { recordBuilderSave } from "@/components/estimator/builder/builderService";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";
import { preflightBuilderSourceMutation, updateBuilderSourceProject } from "@/components/estimator/builder/sourceProjectPersistence";
import { ensureIdempotentEntityCreate, newCreationRequestKey } from "@/components/estimator/idempotentEntityCreate";
import ModuleActionBar from "@/components/estimator/moduleShared/ModuleActionBar";
import ModuleTemplateDialog from "@/components/estimator/moduleShared/ModuleTemplateDialog";
import { saveModuleProjectCopy } from "@/components/estimator/moduleShared/moduleProjectActions";
import CustomerPricingTab from "@/components/markup/CustomerPricingTab";
import { categorizePaintProject } from "@/components/markup/projectCategorizer";
import { calculateSavedCustomerPricing } from "@/components/markup/savedCustomerPricing";
import { newBuilderItemId, seedBuilderItemIds } from "@/components/estimator/builder/itemIdentity";
import {
  PAINT_THICKNESSES,
  autoPaintMaskSqft,
  normalizePaintingItem,
} from "@/components/estimator/paint/paintCalc";
import {
  calcPaintingProject,
  hasIssueFor,
  hasPaintCostSnapshot,
  paintDraftValue,
} from "@/components/estimator/paint/paintPricingAvailability";
import { staffEntities } from "@/components/staff/staffEntities";

const money = (value) => Number(value || 0).toLocaleString("en-US", { style: "currency", currency: "USD" });
const number = (value, digits = 2) => Number(value || 0).toLocaleString("en-US", { maximumFractionDigits: digits });

// Saved-fallback display: a non-finite live value is either the saved
// acknowledged snapshot (shown plainly) or genuinely unsaved ("Not saved").
const sumOrNull = (...xs) => xs.every((v) => Number.isFinite(v)) ? xs.reduce((s, v) => s + v, 0) : null;
const moneyCell = (v) => hasPaintCostSnapshot(v)
  ? money(v)
  : <span className="text-amber-700 font-medium">Not saved</span>;
const numCell = (v, digits = 2) => Number.isFinite(v) ? number(v, digits) : "—";

const emptyItem = () => normalizePaintingItem({
  builder_item_id: newBuilderItemId("paint-item"),
  paint_colors: [""],
});

export default function PaintingEstimator({ embedded = false, embeddedProjectId = null, embeddedEstimateId = null, onClose, onSaved }) {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const editId = embeddedProjectId || searchParams.get("edit") || searchParams.get("id");
  const estimateId = embeddedEstimateId || searchParams.get("estimateId");
  const [project, setProject] = useState(null);
  const [settings, setSettings] = useState({});
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const persistedProjectIdRef = useRef(editId || "");
  const createAttemptRef = useRef({ signature: "", key: "" });
  const copyAttemptRef = useRef({ signature: "", key: "" });
  const [templateMode, setTemplateMode] = useState(null);

  useEffect(() => {
    persistedProjectIdRef.current = editId || "";
    createAttemptRef.current = { signature: "", key: "" };
    copyAttemptRef.current = { signature: "", key: "" };
  }, [editId]);

  useEffect(() => {
    let active = true;
    const load = async () => {
      setLoading(true);
      try {
        const [settingsRows, existing, estimate] = await Promise.all([
          loadAllEntityRows({ entity: Settings, sort: "created_date", label: "Estimator Settings" }),
          editId ? Project.get(editId) : Promise.resolve(null),
          estimateId ? staffEntities.AllInOneEstimate.get(estimateId) : Promise.resolve(null),
        ]);
        if (!active) return;
        const settingsMap = {};
        (settingsRows || []).forEach((row) => { settingsMap[row.setting_name] = row.setting_value; });
        setSettings(settingsMap);
        const suppliesDefault = Number(settingsMap.default_paint_supplies_per_sqft) || 1.25;
        if (existing) {
          setProject({
            ...existing,
            client_name: estimate?.client_name || existing.client_name || "",
            customer_id: estimate?.customer_id || existing.customer_id || null,
            estimate_number: estimate?.estimate_number || existing.estimate_number || "",
            items: seedBuilderItemIds((existing.items || []).map(normalizePaintingItem), "paint-item"),
            paint_supplies_per_sqft: existing.paint_supplies_per_sqft ?? suppliesDefault,
          });
        } else {
          setProject({
            project_name: estimate?.project_name ? `${estimate.project_name} — Painting` : "",
            client_name: estimate?.client_name || "",
            customer_id: estimate?.customer_id || null,
            estimate_number: estimate?.estimate_number || "",
            hyperlink: "",
            status: "draft",
            items: [],
            paint_supplies_per_sqft: suppliesDefault,
            notes: settingsMap.default_notes_template || "",
          });
        }
      } catch (e) {
        console.error("Could not load Painting estimator:", e);
        if (active) setError(e.message || "Could not load Painting estimator.");
      } finally {
        if (active) setLoading(false);
      }
    };
    load();
    return () => { active = false; };
  }, [editId, estimateId]);

  // Pricing-availability: one strict calc pass shared by the banner, the
  // totals panel, the per-field diagnostics, and the save guard.
  const priced = useMemo(
    () => (project ? calcPaintingProject(project, settings) : null),
    [project, settings]
  );
  const calculated = priced?.calc || null;
  const totals = calculated?.totals || {};
  const allIssues = priced?.issues || [];
  // Any settings-side unavailability → stronger save message; any issue at
  // all blocks the save — unavailable pricing is never written as $0.
  const catalogBlocked = allIssues.some((i) => i.kind === "paint_catalog");
  const pricingBlocked = allIssues.length > 0;
  const pricingUnavailable = !!calculated?.pricingUnavailable;
  const itemIssues = (index) => allIssues.filter((i) => i.itemIndex === index);

  const patchProject = (changes) => setProject((prev) => ({ ...prev, ...changes }));

  const patchItem = (index, changes, { autoMask = false } = {}) => {
    setProject((prev) => {
      const items = [...(prev.items || [])];
      let item = normalizePaintingItem({ ...items[index], ...changes });
      if (item.item_type === "lettering") item.quantity = 1;
      if (Object.prototype.hasOwnProperty.call(changes, "width") && item.item_type === "lettering") {
        const height = Number(item.width || 0);
        item.letter_size = height <= 4 ? "extra_small"
          : height <= 8 ? "small"
            : height <= 12 ? "normal"
              : height <= 20 ? "medium"
                : height <= 30 ? "large"
                  : "extra_large";
      }
      if (autoMask) item.paint_mask_sqft = autoPaintMaskSqft(item);
      items[index] = item;
      return { ...prev, items };
    });
  };

  const addItem = () => {
    setTimeout(() => document.querySelector(`input[data-item-desc="${(project.items || []).length}"]`)?.focus(), 60);
    patchProject({ items: [...(project.items || []), emptyItem()] });
  };
  const removeItem = (index) => {
    const label = project.items?.[index]?.description || `item ${index + 1}`;
    if (!window.confirm(`Delete "${label}"?`)) return;
    patchProject({ items: project.items.filter((_, i) => i !== index) });
  };

  const updateColor = (itemIndex, colorIndex, value) => {
    const colors = [...(project.items[itemIndex].paint_colors || [])];
    colors[colorIndex] = value;
    patchItem(itemIndex, { paint_colors: colors });
  };
  const addColor = (itemIndex) => patchItem(itemIndex, { paint_colors: [...(project.items[itemIndex].paint_colors || []), ""] });
  const removeColor = (itemIndex, colorIndex) => patchItem(itemIndex, {
    paint_colors: (project.items[itemIndex].paint_colors || []).filter((_, i) => i !== colorIndex),
  });

  // Ctrl+S / Cmd+S saves the section without leaving the editor.
  useEffect(() => {
    const handler = (e) => {
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "s") {
        e.preventDefault();
        if (!saving) saveProject();
      }
    };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, [saving]);
  // Block accidental navigation while a save is in flight.
  useEffect(() => {
    if (!saving) return undefined;
    const warn = (e) => { e.preventDefault(); e.returnValue = ""; };
    window.addEventListener("beforeunload", warn);
    return () => window.removeEventListener("beforeunload", warn);
  }, [saving]);
  const saveProject = async () => {
    // Pricing-availability guard: a malformed or unavailable pricing input
    // must never be persisted as $0 or an inferred default. Block the write
    // and point the user at the flagged values.
    if (pricingBlocked) {
      setError(catalogBlocked
        ? "Save paused: a Painting Settings value is missing or unusable — update it in Painting Settings, then save."
        : "Save paused: fix the flagged pricing values before saving — unavailable pricing is never written as $0.");
      return;
    }
    if (!project?.project_name?.trim() || !project?.client_name?.trim()) {
      setError("Project name and client name are required.");
      return;
    }
    setSaving(true);
    setError("");
    try {
      const cleanItems = (calculated?.items || []).map((item) => ({
        ...item,
        paint_colors: (item.paint_colors || []).filter((color) => String(color || "").trim()),
      }));
      const pricingProject = {
        ...project,
        total_paint_mask_cost: totals.total_paint_mask_cost,
        total_liquid_paint_and_supplies_cost: totals.total_liquid_paint_and_supplies_cost,
        total_labor_cost: totals.total_labor_cost,
      };
      const customerPricing = project.customer_pricing?.applied === true
        ? await calculateSavedCustomerPricing({
            project: pricingProject,
            categorize: categorizePaintProject,
            tierNumber: project.customer_pricing?.tier_number,
          })
        : project.customer_pricing;
      const payload = {
        project_name: project.project_name,
        client_name: project.client_name,
        customer_id: project.customer_id || null,
        estimate_number: project.estimate_number || "",
        hyperlink: project.hyperlink || "",
        status: "calculated",
        items: cleanItems,
        paint_supplies_per_sqft: Number(project.paint_supplies_per_sqft || 0),
        total_paint_mask_cost: totals.total_paint_mask_cost,
        total_liquid_paint_and_supplies_cost: totals.total_liquid_paint_and_supplies_cost,
        total_labor_cost: totals.total_labor_cost,
        customer_pricing: customerPricing,
        notes: project.notes || "",
      };

      let projectId = persistedProjectIdRef.current || editId || "";
      let savedProject;
      if (projectId) {
        savedProject = await updateBuilderSourceProject({
          entity: Project,
          sourceId: projectId,
          expectedUpdatedAt: project.updated_date,
          data: payload,
          estimateId,
          label: "Painting project",
        });
      } else {
        await preflightBuilderSourceMutation({ estimateId });
        const signature = JSON.stringify(payload);
        if (createAttemptRef.current.signature !== signature) {
          createAttemptRef.current = {
            signature,
            key: newCreationRequestKey("painting_project"),
          };
        }
        savedProject = await ensureIdempotentEntityCreate({
          entity: Project,
          keyField: "creation_request_key",
          key: createAttemptRef.current.key,
          data: payload,
          label: "Painting project",
        });
        if (!savedProject?.id) throw new Error("Painting project create could not be verified.");
        projectId = savedProject.id;
        persistedProjectIdRef.current = projectId;
      }

      if (!savedProject?.id) savedProject = await Project.get(projectId);
      if (estimateId) {
        await recordBuilderSave({
          estimateId,
          line: { project_id: projectId, module_key: "painting" },
          sourceProject: savedProject,
          liveTotal: totals.total_cost,
        });
      }
      setProject((prev) => ({ ...prev, ...savedProject, items: seedBuilderItemIds(savedProject.items || [], "paint-item") }));
      onSaved?.();
      if (!embedded && !editId) navigate(`/PaintingEstimator?id=${projectId}`);
    } catch (e) {
      console.error("Could not save Painting estimator:", e);
      setError(e.message || "Could not save Painting estimator.");
    } finally {
      setSaving(false);
    }
  };

  // #78 — clone the current save payload into a brand-new Painting project.
  const handleSaveAsCopy = async () => {
    if (pricingBlocked) {
      setError("Save paused: fix the flagged pricing values before saving a copy — unavailable pricing is never written as $0.");
      return;
    }
    setSaving(true);
    setError("");
    try {
      const cleanItems = (calculated?.items || []).map((item) => ({
        ...item,
        paint_colors: (item.paint_colors || []).filter((color) => String(color || "").trim()),
      }));
      const copy = await saveModuleProjectCopy({
        entity: Project,
        payload: {
          project_name: project.project_name,
          client_name: project.client_name,
          customer_id: project.customer_id || null,
          estimate_number: project.estimate_number || "",
          hyperlink: project.hyperlink || "",
          status: "calculated",
          items: cleanItems,
          paint_supplies_per_sqft: Number(project.paint_supplies_per_sqft || 0),
          total_paint_mask_cost: totals.total_paint_mask_cost,
          total_liquid_paint_and_supplies_cost: totals.total_liquid_paint_and_supplies_cost,
          total_labor_cost: totals.total_labor_cost,
          customer_pricing: project.customer_pricing,
          notes: project.notes || "",
        },
        attemptRef: copyAttemptRef,
        keyPrefix: "painting_project_copy",
        baseName: project.project_name || "Painting",
        label: "Painting project copy",
      });
      if (embedded) onSaved?.();
      else navigate(`/PaintingEstimator?id=${copy.id}`);
    } catch (e) {
      console.error("Could not copy Painting estimator:", e);
      setError(e.message || "Could not copy Painting estimator.");
    } finally {
      setSaving(false);
    }
  };

  // #79 — template payload = the editable setup a user would reuse.
  const buildPaintingTemplateData = (p) => ({
    items: p.items || [],
    paint_supplies_per_sqft: p.paint_supplies_per_sqft,
    notes: p.notes,
  });

  if (loading) return <div className="p-10 text-center text-gray-400">Loading Painting Builder…</div>;
  if (!project) return <div className="p-10 text-center text-red-600">{error || "Painting project not found."}</div>;

  return (
    <div className="min-h-full bg-gray-50">
      <div className="max-w-[1220px] mx-auto p-4 sm:p-5">
        <div className="flex items-center justify-between gap-3 mb-4">
          {embedded ? (
            <button type="button" onClick={onClose} className="inline-flex items-center gap-1 text-[12px] font-semibold text-gray-600 hover:text-gray-900">
              <ArrowLeft className="w-4 h-4" /> Back to products
            </button>
          ) : (
            <Link to={estimateId ? `/EstimateDetail?id=${estimateId}` : "/Estimator"} className="inline-flex items-center gap-1 text-[12px] font-semibold text-gray-600 hover:text-gray-900">
              <ArrowLeft className="w-4 h-4" /> Back to estimator
            </Link>
          )}
          {project?.updated_date && (<div className="mt-1 text-[10px] text-gray-400">Last saved {new Date(project.updated_date).toLocaleString()}</div>)}
          <Button onClick={saveProject} disabled={saving || !project.project_name?.trim() || !project.client_name?.trim()} className="h-[32px] bg-[#454545] hover:bg-[#353535] text-white text-[12px] font-semibold">
            <Save className="w-4 h-4 mr-1.5" /> {saving ? "Saving…" : "Save Painting"}
          </Button>
          <ModuleActionBar
            onTemplates={() => setTemplateMode("load")}
            onSaveAsTemplate={() => setTemplateMode("save")}
            onSaveAsCopy={handleSaveAsCopy}
            estimateId={estimateId}
            saving={saving}
          />
        </div>

        <div className="flex items-center gap-3 mb-4">
          <div className="w-9 h-9 rounded-md bg-sky-100 text-sky-700 flex items-center justify-center"><Palette className="w-5 h-5" /></div>
          <div>
            <h1 className="text-[20px] font-bold text-gray-900">Painting Builder</h1>
            <p className="text-[11px] text-gray-500">Panels, dimensional lettering and complex shapes using the migrated SignEstimate Pro paint formulas.</p>
          </div>
        </div>

        {error && <div className="mb-3 px-3 py-2 text-[12px] text-red-700 bg-red-50 border border-red-200 rounded">{error}</div>}

        {/* Pricing-availability banner — visible on every state so a blocked
            save always shows why. */}
        {allIssues.length > 0 && (
          <div
            role="status"
            id="paint-pricing-issues"
            className="mb-3 flex items-start gap-2 text-[11px] text-amber-900 bg-amber-50 border border-amber-300 rounded px-3 py-2"
          >
            <AlertTriangle className="w-4 h-4 mt-0.5 flex-shrink-0 text-amber-600" />
            <div className="min-w-0">
              <div className="font-semibold">
                Pricing unavailable — {allIssues.length} value{allIssues.length === 1 ? "" : "s"} need{allIssues.length === 1 ? "s" : ""} attention before this estimate can be priced or saved.
              </div>
              <ul className="mt-1 space-y-0.5 list-disc list-inside">
                {allIssues.slice(0, 5).map((it, i) => <li key={i}>{it.message}</li>)}
                {allIssues.length > 5 && <li>…and {allIssues.length - 5} more</li>}
              </ul>
            </div>
          </div>
        )}

        <div className="grid grid-cols-1 xl:grid-cols-[minmax(0,1fr)_310px] gap-4">
          <div className="space-y-4 min-w-0">
            <section className="bg-white border border-gray-200 rounded-md p-4">
              <div className="text-[12px] font-bold text-gray-800 mb-3">Project</div>
              <div className="grid sm:grid-cols-2 gap-3">
                <label className="text-[11px] text-gray-600">Project name
                  <Input value={project.project_name || ""} onChange={(e) => patchProject({ project_name: e.target.value })} className="mt-1 h-[32px] text-[12px]" />
                </label>
                <label className="text-[11px] text-gray-600">Client
                  <Input value={project.client_name || ""} onChange={(e) => patchProject({ client_name: e.target.value })} disabled={!!estimateId} className="mt-1 h-[32px] text-[12px]" />
                </label>
                <label className="text-[11px] text-gray-600">Estimate number
                  <Input value={project.estimate_number || ""} onChange={(e) => patchProject({ estimate_number: e.target.value })} disabled={!!estimateId} className="mt-1 h-[32px] text-[12px]" />
                </label>
                <label className="text-[11px] text-gray-600">Paint application supplies / sq ft / color
                  <Input type="number" step="0.01" min="0" value={project.paint_supplies_per_sqft ?? ""} onChange={(e) => patchProject({ paint_supplies_per_sqft: paintDraftValue(e.target.value) })}
                    aria-invalid={hasIssueFor(allIssues, "paint_supplies_per_sqft") || undefined}
                    aria-describedby={hasIssueFor(allIssues, "paint_supplies_per_sqft") ? "paint-pricing-issues" : undefined}
                    className="mt-1 h-[32px] text-[12px]" />
                </label>
              </div>
              <label className="block text-[11px] text-gray-600 mt-3">Notes
                <Textarea value={project.notes || ""} onChange={(e) => patchProject({ notes: e.target.value })} className="mt-1 min-h-[70px] text-[12px]" />
              </label>
            </section>

            <section className="bg-white border border-gray-200 rounded-md">
              <div className="px-4 py-3 border-b border-gray-200 flex items-center justify-between gap-3">
                <div>
                  <div className="text-[12px] font-bold text-gray-800">Paint Items</div>
                  <div className="text-[10px] text-gray-500">Geometry drives paintable area; colors drive paint, mask and labor.</div>
                </div>
                <Button onClick={addItem} variant="outline" className="h-[30px] px-3 text-[11px]"><Plus className="w-3.5 h-3.5 mr-1" /> Add Item</Button>
              </div>

              {(project.items || []).length === 0 ? (
                <div className="py-12 text-center text-[12px] text-gray-400">No paint items yet.</div>
              ) : (
                <div className="divide-y divide-gray-100">
                  {project.items.map((rawItem, index) => {
                    const item = calculated.items[index] || rawItem;
                    const lettering = rawItem.item_type === "lettering";
                    const rowIssues = itemIssues(index);
                    const rowIssuesId = `paint-item-${index}-issues`;
                    const fieldFlag = (field) => hasIssueFor(allIssues, field, index) || undefined;
                    const fieldDesc = (field) => hasIssueFor(allIssues, field, index) ? rowIssuesId : undefined;
                    return (
                      <div key={rawItem.builder_item_id || index} className="p-4 space-y-3">
                        <div className="flex items-center gap-2">
                          <span className="w-6 h-6 rounded bg-gray-100 text-gray-600 flex items-center justify-center text-[10px] font-bold">{index + 1}</span>
                          <Input data-item-desc={index} value={rawItem.description || ""} onChange={(e) => patchItem(index, { description: e.target.value })} placeholder="Item description" className="h-[30px] text-[12px] flex-1" />
                          <button type="button" onClick={() => removeItem(index)} className="w-8 h-8 inline-flex items-center justify-center rounded text-red-500 hover:bg-red-50" aria-label="Remove item"><Trash2 className="w-4 h-4" /></button>
                        </div>

                        {!lettering && (
                          <div className="flex flex-wrap items-center gap-1.5">
                            <span className="text-[9px] font-bold tracking-wide text-gray-400">SURFACE PRESETS</span>
                            {[["4′×8′ face", 48, 96], ["8′×4′ face", 96, 48], ["2′×4′ face", 24, 48], ["4′×4′ face", 48, 48]].map(([label, l, w]) => (
                              <button key={label} type="button" onClick={() => patchItem(index, { length: l, width: w }, { autoMask: true })} className="px-2 h-[24px] rounded border border-gray-300 text-[10px] text-gray-600 hover:bg-gray-50">{label}</button>
                            ))}
                          </div>
                        )}
                        <div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-2.5">
                          <Field label="Type">
                            <Select value={rawItem.item_type || "panel"} onValueChange={(value) => patchItem(index, { item_type: value }, { autoMask: true })}>
                              <SelectTrigger className="h-[30px] text-[11px]"
                                aria-invalid={fieldFlag("item_type")}
                                aria-describedby={fieldDesc("item_type")}><SelectValue /></SelectTrigger>
                              <SelectContent>
                                <SelectItem value="panel">Panel</SelectItem>
                                <SelectItem value="lettering">Lettering</SelectItem>
                                <SelectItem value="complex_shapes">Complex Shape</SelectItem>
                              </SelectContent>
                            </Select>
                          </Field>
                          <Field label="Thickness">
                            <Select value={rawItem.thickness || "1/2"} onValueChange={(value) => patchItem(index, { thickness: value }, { autoMask: true })}>
                              <SelectTrigger className="h-[30px] text-[11px]"
                                aria-invalid={fieldFlag("thickness")}
                                aria-describedby={fieldDesc("thickness")}><SelectValue /></SelectTrigger>
                              <SelectContent>{PAINT_THICKNESSES.map((size) => <SelectItem value={size} key={size}>{size}&quot;</SelectItem>)}</SelectContent>
                            </Select>
                          </Field>
                          <Field label={lettering ? "Letter height (in)" : "Length (in)"}>
                            <Input type="number" min="0" step="0.01" value={rawItem[lettering ? "width" : "length"] ?? ""} onChange={(e) => patchItem(index, { [lettering ? "width" : "length"]: paintDraftValue(e.target.value) }, { autoMask: true })}
                              aria-invalid={fieldFlag(lettering ? "width" : "length")}
                              aria-describedby={fieldDesc(lettering ? "width" : "length")}
                              className="h-[30px] text-[11px]" />
                          </Field>
                          <Field label={lettering ? "Number of letters" : "Width (in)"}>
                            <Input type="number" min="0" step={lettering ? "1" : "0.01"} value={rawItem[lettering ? "length" : "width"] ?? ""} onChange={(e) => patchItem(index, { [lettering ? "length" : "width"]: paintDraftValue(e.target.value) }, { autoMask: true })}
                              aria-invalid={fieldFlag(lettering ? "length" : "width")}
                              aria-describedby={fieldDesc(lettering ? "length" : "width")}
                              className="h-[30px] text-[11px]" />
                          </Field>
                          {!lettering && <Field label="Quantity"><Input type="number" min="1" step="1" value={rawItem.quantity ?? ""} onChange={(e) => patchItem(index, { quantity: paintDraftValue(e.target.value) })}
                            aria-invalid={fieldFlag("quantity")}
                            aria-describedby={fieldDesc("quantity")}
                            className="h-[30px] text-[11px]" /></Field>}
                          <Field label="Paint sides">
                            <Select value={rawItem.paint_sides || "one_side"} onValueChange={(value) => patchItem(index, { paint_sides: value })}>
                              <SelectTrigger className="h-[30px] text-[11px]"
                                aria-invalid={fieldFlag("paint_sides")}
                                aria-describedby={fieldDesc("paint_sides")}><SelectValue /></SelectTrigger>
                              <SelectContent><SelectItem value="one_side">One side + edges</SelectItem><SelectItem value="both_sides">Both sides + edges</SelectItem></SelectContent>
                            </Select>
                          </Field>
                          {rawItem.item_type === "complex_shapes" && <Field label="Edge complexity"><Input type="number" min="0" step="0.1" value={rawItem.edge_complexity_multiplier ?? ""} onChange={(e) => patchItem(index, { edge_complexity_multiplier: paintDraftValue(e.target.value) })}
                            aria-invalid={fieldFlag("edge_complexity_multiplier")}
                            aria-describedby={fieldDesc("edge_complexity_multiplier")}
                            className="h-[30px] text-[11px]" /></Field>}
                          <Field label="Paint mask sq ft"><Input type="number" min="0" step="0.01" value={rawItem.paint_mask_sqft ?? ""} onChange={(e) => patchItem(index, { paint_mask_sqft: paintDraftValue(e.target.value) })}
                            aria-invalid={fieldFlag("paint_mask_sqft")}
                            aria-describedby={fieldDesc("paint_mask_sqft")}
                            className="h-[30px] text-[11px]" /></Field>
                          <Field label="Item fixed waste (gal)"><Input type="number" min="0" step="0.01" value={rawItem.fixed_waste_gallons ?? ""} onChange={(e) => patchItem(index, { fixed_waste_gallons: paintDraftValue(e.target.value) })}
                            aria-invalid={fieldFlag("fixed_waste_gallons")}
                            aria-describedby={fieldDesc("fixed_waste_gallons")}
                            className="h-[30px] text-[11px]" /></Field>
                          <Field label="Base supplies"><Input type="number" min="0" step="0.01" value={rawItem.base_supplies_cost ?? ""} onChange={(e) => patchItem(index, { base_supplies_cost: paintDraftValue(e.target.value) })}
                            aria-invalid={fieldFlag("base_supplies_cost")}
                            aria-describedby={fieldDesc("base_supplies_cost")}
                            className="h-[30px] text-[11px]" /></Field>
                        </div>

                        {/* Per-item diagnostics — a malformed value stays on
                            the row and is explained here, never dropped. */}
                        {rowIssues.length > 0 && (
                          <div role="status" id={rowIssuesId}
                            className="flex items-start gap-2 text-[11px] text-amber-900 bg-amber-50 border border-amber-200 rounded px-2 py-1">
                            <AlertTriangle className="w-3 h-3 mt-0.5 flex-shrink-0" />
                            <div className="space-y-0.5">
                              {rowIssues.map((it, i) => <div key={i}>{it.message}</div>)}
                            </div>
                          </div>
                        )}

                        <div className="bg-gray-50 border border-gray-100 rounded p-2.5">
                          <div className="flex items-center justify-between mb-2">
                            <div className="text-[10px] font-bold uppercase tracking-wide text-gray-500">Paint colors</div>
                            <button type="button" onClick={() => addColor(index)} className="text-[10px] font-semibold text-sky-700 hover:text-sky-900">+ Add color</button>
                          </div>
                          {(rawItem.paint_colors || []).length === 0 ? <div className="text-[10px] text-gray-400">No colors selected — no liquid paint is charged.</div> : (
                            <div className="flex flex-wrap gap-2">
                              {(rawItem.paint_colors || []).map((color, colorIndex) => (
                                <div className="flex items-center gap-1" key={colorIndex}>
                                  <Input value={color || ""} onChange={(e) => updateColor(index, colorIndex, e.target.value)} placeholder="PMS / color" className="h-[28px] w-[145px] text-[11px]" />
                                  <button type="button" onClick={() => removeColor(index, colorIndex)} className="w-6 h-6 rounded text-gray-400 hover:text-red-600 hover:bg-white">×</button>
                                </div>
                              ))}
                            </div>
                          )}
                        </div>

                        <div className="grid grid-cols-2 md:grid-cols-5 gap-2 text-[10px]">
                          <Metric label="Paintable area" value={Number.isFinite(item.paintable_sqft) ? `${number(item.paintable_sqft)} sf` : "—"} />
                          <Metric label="Paint mask" value={moneyOrHeld(item.supplies_cost)} />
                          <Metric label="Paint + supplies" value={moneyOrHeld(item.paint_cost)} />
                          <Metric label="Labor" value={moneyOrHeld(item.labor_cost)} />
                          <Metric label="Paint volume" value={Number.isFinite(item.paint_gallons) ? `${number(item.paint_gallons, 3)} gal` : "—"} />
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </section>
          </div>

          <aside className="space-y-3">
            <section className="bg-white border border-gray-200 rounded-md sticky top-4">
              <div className="px-4 py-3 border-b border-gray-200">
                <div className="text-[12px] font-bold text-gray-800">Cost Summary</div>
                <div className="text-[10px] text-gray-500">Internal Builder cost before estimate-level markup.</div>
              </div>
              <div className="p-4 space-y-2 text-[11px]">
                {pricingUnavailable && (
                  <p className="text-[11px] text-amber-800 mb-1">Saved amounts (not current pricing) — fix the flagged values to reprice.</p>
                )}
                <SummaryRow label="Paint mask" value={moneyCell(Number.isFinite(totals.total_paint_mask_cost) ? totals.total_paint_mask_cost : project.total_paint_mask_cost)} />
                <SummaryRow label="Liquid paint & supplies" value={moneyCell(Number.isFinite(totals.total_liquid_paint_and_supplies_cost) ? totals.total_liquid_paint_and_supplies_cost : project.total_liquid_paint_and_supplies_cost)} />
                <SummaryRow label="Painting labor" value={moneyCell(Number.isFinite(totals.total_labor_cost) ? totals.total_labor_cost : project.total_labor_cost)} />
                <div className="border-t border-gray-200 pt-2 mt-2 flex justify-between items-center">
                  <span className="font-bold text-gray-800">Total cost</span>
                  <span className="text-[16px] font-bold text-gray-900">{moneyCell(Number.isFinite(totals.total_cost) ? totals.total_cost : sumOrNull(project.total_paint_mask_cost, project.total_liquid_paint_and_supplies_cost, project.total_labor_cost))}</span>
                </div>
              </div>
              <div className="px-4 py-3 border-t border-gray-100 bg-gray-50 space-y-1.5 text-[10px] text-gray-500">
                <SummaryRow label="Paint needed" value={`${numCell(totals.total_paint_gallons, 3)} gal`} subtle />
                <SummaryRow label="Labor time" value={`${numCell(totals.total_labor_hours)} hr`} subtle />
                <SummaryRow label="Unique colors" value={numCell(totals.unique_color_count, 0)} subtle />
                <SummaryRow label="Mixes" value={numCell(totals.number_of_mixes, 0)} subtle />
                <SummaryRow label="Setup / cleanup" value={`${numCell(totals.setup_hours)} hr`} subtle />
                <SummaryRow label="Mixing" value={`${numCell(totals.mixing_hours)} hr`} subtle />
              </div>
              <div className="px-4 py-3 border-t border-gray-100 text-[10px] text-gray-500">
                Mixed paint rate: <span className="font-semibold text-gray-700">{Number.isFinite(calculated.liquidPaintRate) ? `${money(calculated.liquidPaintRate)}/sf` : "—"}</span>
              </div>
            </section>
          </aside>
        </div>

        <div className="mt-4">
          <CustomerPricingTab
            project={{
              ...project,
              // Feed live totals so the categorizer sees current numbers. Held
              // values surface as 0 here — this tab is advisory only; the
              // blocked save keeps them from reaching the record.
              total_paint_mask_cost: totals.total_paint_mask_cost ?? 0,
              total_liquid_paint_and_supplies_cost: totals.total_liquid_paint_and_supplies_cost ?? 0,
              total_labor_cost: totals.total_labor_cost ?? 0,
            }}
            categorize={categorizePaintProject}
            accentColor="blue"
            onApplyTier={(tier) => patchProject({
              customer_pricing: { ...(project.customer_pricing || {}), applied: true, tier_number: tier },
            })}
          />
        </div>
      </div>
      <ModuleTemplateDialog
        open={!!templateMode}
        mode={templateMode}
        onClose={() => setTemplateMode(null)}
        project={project}
        onApply={(data) => patchProject(data)}
        moduleKey="painting"
        title="Painting"
        buildTemplateData={buildPaintingTemplateData}
        describeTemplate={(t) => `${(t.project_data?.items || []).length} items`}
      />
    </div>
  );
}

function moneyOrHeld(v) {
  return Number.isFinite(v) ? money(v) : "—";
}

function Field({ label, children }) {
  return <label className="text-[10px] text-gray-500 min-w-0"><span className="block mb-1">{label}</span>{children}</label>;
}

function Metric({ label, value }) {
  return <div className="bg-white border border-gray-100 rounded px-2 py-1.5"><div className="text-gray-400">{label}</div><div className="font-semibold text-gray-700 mt-0.5">{value}</div></div>;
}

function SummaryRow({ label, value, subtle = false }) {
  return <div className={`flex items-center justify-between gap-3 ${subtle ? "text-gray-500" : "text-gray-600"}`}><span>{label}</span><span className={subtle ? "font-medium" : "font-semibold text-gray-800"}>{value}</span></div>;
}

files.normalized:
// Vinyl Estimator — tabbed estimator with multiple vinyl workflows + installation.
// Tabs: Project Info → Vinyl Workflows → Installation → Travel & Crew → Summary
// Each workflow has its own vinyl + machines + parts + roll layout, so different
// materials never get nested onto the same physical roll.

import { useEffect, useMemo, useState, useCallback, useRef } from "react";
import { Link, useNavigate, useSearchParams } from "react-router-dom";
import {
  VinylProject, VinylInventory, VinylMachine,
  Settings, ChannelLetterInstallEquipment,
} from "@/api/gatedEntities";
import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Button } from "@/components/ui/button";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { ArrowLeft, Droplets, Loader2, FileText, Layers, HardHat, Calculator, Plus, MapPin, Settings as SettingsIcon, ChevronsUpDown, ChevronsDownUp, BookmarkPlus, ClipboardPaste, UploadCloud, AlertTriangle, TrendingUp } from "lucide-react";
import CustomerPricingTab from "@/components/markup/CustomerPricingTab";
import { categorizeVinylProject } from "@/components/markup/projectCategorizer";
import { calculateSavedCustomerPricing } from "@/components/markup/savedCustomerPricing";
import { recordBuilderSave } from "@/components/estimator/builder/builderService";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";
import { preflightBuilderSourceMutation, updateBuilderSourceProject } from "@/components/estimator/builder/sourceProjectPersistence";
import { ensureIdempotentEntityCreate, newCreationRequestKey } from "@/components/estimator/idempotentEntityCreate";
import ModuleActionBar from "@/components/estimator/moduleShared/ModuleActionBar";
import ModuleTemplateDialog from "@/components/estimator/moduleShared/ModuleTemplateDialog";
import { saveModuleProjectCopy } from "@/components/estimator/moduleShared/moduleProjectActions";
import AddressAutocomplete from "@/components/channelLetterInstall/AddressAutocomplete";
import EquipmentSelector from "@/components/channelLetterInstall/EquipmentSelector";
import PersonnelSelector from "@/components/channelLetterInstall/PersonnelSelector";
import TravelCostCard from "@/components/channelLetterInstall/TravelCostCard";

import VinylWorkflowCard from "@/components/vinylEstimator/VinylWorkflowCard";
import VinylProjectSummaryCard from "@/components/vinylEstimator/VinylProjectSummaryCard";
import VinylBulkImportDialog from "@/components/vinylEstimator/VinylBulkImportDialog";
import VinylPartsLibraryDialog from "@/components/vinylEstimator/VinylPartsLibraryDialog";
import VinylArtworkUploadDialog from "@/components/vinylEstimator/VinylArtworkUploadDialog";
import VinylMoveToWorkflowMenu from "@/components/vinylEstimator/VinylMoveToWorkflowMenu";
import {
  blankVinylProject, blankWorkflow, migrateProject, rollupVinylProject,
} from "@/components/vinylEstimator/vinylProjectHelpers";
import {
  calcVinylWorkflow, vinylProjectInputIssues, hasVinylCostSnapshot,
} from "@/components/vinylEstimator/vinylPricingAvailability";
import { staffEntities } from "@/components/staff/staffEntities";

const fmt = (n) => `$${Number(n || 0).toFixed(2)}`;
const sumOrNull = (...xs) => xs.every(v => Number.isFinite(v)) ? xs.reduce((s, v) => s + v, 0) : null;

export default function VinylEstimator({ embedded = false, embeddedProjectId = null, embeddedEstimateId = null, onClose, onSaved }) {
  const [search] = useSearchParams();
  // Embedded All-In-One context wins over standalone query parameters.
  const projectId = embeddedProjectId || search.get("id") || search.get("edit");
  const estimateId = embeddedEstimateId || search.get("estimateId");
  const navigate = useNavigate();

  const [project, setProject] = useState(blankVinylProject());
  const [vinyls, setVinyls] = useState([]);
  const [machines, setMachines] = useState([]);
  const [settings, setSettings] = useState({});
  const [equipmentInventory, setEquipmentInventory] = useState([]);
  const [estimateContext, setEstimateContext] = useState(null);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState("");
  const [saving, setSaving] = useState(false);
  const [activeTab, setActiveTab] = useState("project");
  const persistedProjectIdRef = useRef(projectId || "");
  const createAttemptRef = useRef({ signature: "", key: "" });
  const copyAttemptRef = useRef({ signature: "", key: "" });
  const [templateMode, setTemplateMode] = useState(null);

  useEffect(() => {
    persistedProjectIdRef.current = projectId || "";
    createAttemptRef.current = { signature: "", key: "" };
    copyAttemptRef.current = { signature: "", key: "" };
  }, [projectId]);

  // Workflow tab UI state
  const [allOpen, setAllOpen] = useState(true);
  const [targetWorkflowIdx, setTargetWorkflowIdx] = useState(null); // index whose toolbar opened the dialog
  const [bulkOpen, setBulkOpen] = useState(false);
  const [libraryOpen, setLibraryOpen] = useState(false);
  const [artworkOpen, setArtworkOpen] = useState(false);
  // Move-part-to-workflow dialog
  const [moveContext, setMoveContext] = useState(null); // { workflowIdx, partIdx }

  // Load everything in parallel
  useEffect(() => {
    const load = async () => {
      setLoading(true);
      setLoadError("");
      try {
        const [vList, mList, sList, eList, p, estimate] = await Promise.all([
          loadAllEntityRows({ entity: VinylInventory, sort: "sort_order", label: "Vinyl inventory" }),
          loadAllEntityRows({ entity: VinylMachine, sort: "sort_order", label: "Vinyl machines" }),
          loadAllEntityRows({ entity: Settings, sort: "created_date", label: "Estimator Settings" }),
          loadAllEntityRows({ entity: ChannelLetterInstallEquipment, sort: "sort_order", label: "Installation equipment" }),
          projectId ? VinylProject.get(projectId) : Promise.resolve(null),
          estimateId ? staffEntities.AllInOneEstimate.get(estimateId) : Promise.resolve(null),
        ]);
        setVinyls(vList || []);
        setMachines(mList || []);
        setEquipmentInventory(eList || []);
        setEstimateContext(estimate || null);
        const settingsObj = {};
        sList.forEach(s => { settingsObj[s.setting_name] = s.setting_value; });
        setSettings(settingsObj);

        if (p) {
          const migrated = migrateProject(p);
          const firstWorkflow = migrated.workflows?.[0] || blankWorkflow(0);
          const isBlankEmbeddedWorkflow =
            (migrated.workflows || []).length === 1 &&
            !(firstWorkflow.items || []).length &&
            !firstWorkflow.vinyl_id && !firstWorkflow.printer_id && !firstWorkflow.cutter_id && !firstWorkflow.laminator_id;
          const defaultPrinter   = mList.find(m => m.is_default_for_type && (m.machine_type === "printer" || m.machine_type === "print_and_cut")) || mList.find(m => m.machine_type === "printer" || m.machine_type === "print_and_cut");
          const defaultCutter    = mList.find(m => m.is_default_for_type && (m.machine_type === "cutter" || m.machine_type === "print_and_cut")) || mList.find(m => m.machine_type === "cutter" || m.machine_type === "print_and_cut");
          const defaultLaminator = mList.find(m => m.is_default_for_type && m.machine_type === "laminator") || mList.find(m => m.machine_type === "laminator");
          const defaultVinyl     = vList.find(v => v.is_active !== false && !v.is_laminate && v.show_in_vinyl_estimator !== false);
          const workflows = isBlankEmbeddedWorkflow ? [{
            ...firstWorkflow,
            vinyl_id: defaultVinyl?.id || "",
            laminate_id: defaultVinyl?.default_laminate_id || "",
            apply_laminate: !!defaultVinyl?.requires_lamination,
            printer_id: defaultPrinter?.id || "",
            cutter_id: defaultCutter?.id || "",
            laminator_id: defaultLaminator?.id || "",
          }] : migrated.workflows;
          setProject({
            ...migrated,
            workflows,
            client_name: estimate?.client_name || migrated.client_name,
            customer_id: estimate?.customer_id || migrated.customer_id,
            estimate_number: estimate?.estimate_number || migrated.estimate_number,
            site_address: migrated.site_address || estimate?.site_address || "",
          });
        } else {
          // Seed first workflow with sensible defaults
          const defaultPrinter   = mList.find(m => m.is_default_for_type && (m.machine_type === "printer" || m.machine_type === "print_and_cut")) || mList.find(m => m.machine_type === "printer" || m.machine_type === "print_and_cut");
          const defaultCutter    = mList.find(m => m.is_default_for_type && (m.machine_type === "cutter"  || m.machine_type === "print_and_cut")) || mList.find(m => m.machine_type === "cutter" || m.machine_type === "print_and_cut");
          const defaultLaminator = mList.find(m => m.is_default_for_type && m.machine_type === "laminator") || mList.find(m => m.machine_type === "laminator");
          const defaultVinyl     = vList.find(v => v.is_active !== false && !v.is_laminate && v.show_in_vinyl_estimator !== false);

          setProject(prev => ({
            ...prev,
            workflows: [{
              ...prev.workflows[0],
              vinyl_id: defaultVinyl?.id || "",
              laminate_id: defaultVinyl?.default_laminate_id || "",
              apply_laminate: !!defaultVinyl?.requires_lamination,
              printer_id:   defaultPrinter?.id   || "",
              cutter_id:    defaultCutter?.id    || "",
              laminator_id: defaultLaminator?.id || "",
            }],
          }));
        }
      } catch (e) {
        console.error(e);
        setLoadError(e?.message || "Vinyl Builder prerequisites could not be verified.");
      }
      setLoading(false);
    };
    load();
  }, [projectId, estimateId]);

  const updateProject = useCallback((patch) => setProject(prev => ({ ...prev, ...patch })), []);

  const updateWorkflow = (idx, next) => {
    setProject(prev => {
      const wfs = [...prev.workflows];
      wfs[idx] = next;
      return { ...prev, workflows: wfs };
    });
  };
  const addWorkflow = () => {
    setProject(prev => ({
      ...prev,
      workflows: [...prev.workflows, blankWorkflow(prev.workflows.length)],
    }));
  };
  const removeWorkflow = (idx) => {
    if (project.workflows.length === 1) {
      alert("A project must have at least one vinyl workflow.");
      return;
    }
    if (!confirm("Delete this workflow and all its parts?")) return;
    setProject(prev => ({
      ...prev,
      workflows: prev.workflows.filter((_, i) => i !== idx),
    }));
  };
  const duplicateWorkflow = (idx) => {
    setProject(prev => {
      const copy = JSON.parse(JSON.stringify(prev.workflows[idx]));
      copy.id = `wf-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
      copy.name = `${copy.name || `Workflow ${idx + 1}`} (copy)`;
      copy._calc = undefined;
      const next = [...prev.workflows];
      next.splice(idx + 1, 0, copy);
      return { ...prev, workflows: next };
    });
  };

  // Pricing-availability: one strict calc pass per workflow, shared with the
  // cards so the page banner, the tab badges, and the save guard all read the
  // same diagnostics the card displays.
  const workflowPricing = useMemo(
    () => (project.workflows || []).map((wf, idx) => calcVinylWorkflow({ workflow: wf, vinyls, machines, index: idx })),
    [project.workflows, vinyls, machines]
  );
  const projectIssues = useMemo(
    () => vinylProjectInputIssues(project, { settings, equipmentInventory }),
    [project, settings, equipmentInventory]
  );
  const allIssues = useMemo(
    () => [...workflowPricing.flatMap(p => p.issues), ...projectIssues],
    [workflowPricing, projectIssues]
  );
  // Any catalog-side unavailability → stronger save message; any issue at all
  // blocks the save — unavailable pricing is never written as $0.
  const catalogBlocked = allIssues.some(i => i.kind === "vinyl_catalog");
  const pricingBlocked = allIssues.length > 0;
  const pricingUnavailable = pricingBlocked
    || (project.workflows || []).some(wf => wf?._calc?.pricingUnavailable);
  // Tab-surface split so the warn dots point at the right tab.
  const travelIssue = projectIssues.some(i =>
    ["total_travel_cost", "travel_miles_round_trip", "mpg"].includes(i.field)
    || String(i.code).startsWith("vinyl_travel") || String(i.code).startsWith("vinyl_vehicle"));
  const installIssue = projectIssues.some(i =>
    ["selected_equipment", "personnel", "total_cost"].includes(i.field)
    || String(i.code).startsWith("vinyl_equipment") || String(i.code).startsWith("vinyl_personnel_cost")
    || String(i.code).startsWith("vinyl_install_rate"));
  const summaryIssue = projectIssues.some(i =>
    ["supplies_percent_of_materials", "extra_supplies_cost", "markup_percent"].includes(i.field));

  // Project-wide rollup (re-derives when any workflow's _calc changes).
  // Current values win; a held workflow falls back to the saved acknowledged
  // snapshot and only reports "not saved" when no real snapshot exists.
  const rollup = useMemo(() => rollupVinylProject(project), [project]);
  // Max install height for travel/equipment suggestion compatibility
  const totalLaborHours = rollup.laborHours ?? 0;

  // Feature #33 — does any workflow have validation issues?
  const workflowsHaveIssues = useMemo(
    () => (project.workflows || []).some(wf => wf._hasIssues),
    [project.workflows]
  );

  // Helper: add a single part to a specific workflow (used by library + artwork dialogs)
  const addPartToWorkflow = (workflowIdx, part) => {
    if (workflowIdx == null || workflowIdx < 0 || workflowIdx >= project.workflows.length) return;
    const wf = project.workflows[workflowIdx];
    updateWorkflow(workflowIdx, { ...wf, items: [...(wf.items || []), part] });
  };
  // Helper: bulk import to a specific workflow
  const importPartsToWorkflow = (workflowIdx, parts) => {
    if (workflowIdx == null) return;
    const wf = project.workflows[workflowIdx];
    updateWorkflow(workflowIdx, { ...wf, items: [...(wf.items || []), ...parts] });
  };
  // Helper: move a part between workflows
  const movePart = (fromIdx, partIdx, toIdx) => {
    if (fromIdx === toIdx) return;
    const fromWf = project.workflows[fromIdx];
    const toWf = project.workflows[toIdx];
    const part = fromWf.items[partIdx];
    if (!part) return;
    setProject(prev => {
      const wfs = [...prev.workflows];
      wfs[fromIdx] = { ...fromWf, items: fromWf.items.filter((_, i) => i !== partIdx) };
      wfs[toIdx]   = { ...toWf,   items: [...(toWf.items || []), part] };
      return { ...prev, workflows: wfs };
    });
  };

  // Ctrl+S / Cmd+S saves the project without leaving the editor.
  useEffect(() => {
    const handler = (e) => {
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "s") {
        e.preventDefault();
        if (!saving) save();
      }
    };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, [saving]);
  // Block accidental navigation while a save is in flight.
  useEffect(() => {
    if (!saving) return undefined;
    const warn = (e) => { e.preventDefault(); e.returnValue = ""; };
    window.addEventListener("beforeunload", warn);
    return () => window.removeEventListener("beforeunload", warn);
  }, [saving]);
  const save = async () => {
    // Pricing-availability guard: a malformed or unavailable pricing input
    // must never be persisted as $0 or an inferred default. Block the write
    // and point the user at the first tab that owns the issue.
    if (pricingBlocked) {
      const first = allIssues[0];
      const field = first?.field || "";
      const code = String(first?.code || "");
      const tab = first?.index != null ? "workflows"
        : ["supplies_percent_of_materials", "extra_supplies_cost", "markup_percent"].includes(field) ? "summary"
        : (["total_travel_cost", "travel_miles_round_trip", "mpg"].includes(field) || code.startsWith("vinyl_travel") || code.startsWith("vinyl_vehicle")) ? "travel"
        : "install";
      setActiveTab(tab);
      alert(catalogBlocked
        ? "Save paused: a selected vinyl, machine, or equipment record is unavailable or missing required pricing — update it in Vinyl Inventory / Settings, then save."
        : "Save paused: fix the flagged pricing values before saving — unavailable pricing is never written as $0.");
      return;
    }
    if (!project.project_name || !(estimateContext?.client_name || project.client_name)) {
      alert("Please fill in Project Name and Client Name.");
      setActiveTab("project");
      return;
    }
    setSaving(true);
    try {
      // Strip transient _calc from each workflow before saving
      const cleanWorkflows = project.workflows.map(({ _calc, ...rest }) => rest);
      // Flatten parts for entity-level `items` (legacy/reporting), tagged with workflow id
      const flatItems = cleanWorkflows.flatMap(wf =>
        (wf.items || []).map(it => ({ ...it, workflow_id: wf.id, workflow_name: wf.name }))
      );

      const pricingProject = {
        ...project,
        client_name: estimateContext?.client_name || project.client_name,
        customer_id: estimateContext?.customer_id || project.customer_id,
        estimate_number: estimateContext?.estimate_number || project.estimate_number,
        total_vinyl_cost: rollup.vinylCost,
        total_laminate_cost: rollup.laminateCost,
        total_ink_cost: rollup.inkCost,
        total_blade_cost: rollup.bladeCost,
        total_machine_cost: rollup.machineCost,
        total_supplies_cost: rollup.supplies,
        labor_cost: rollup.laborCost,
        total_personnel_cost: rollup.personnelCost,
        total_equipment_cost: rollup.equipmentCost,
        total_travel_cost: rollup.travelCost,
      };
      const customerPricing = await calculateSavedCustomerPricing({
        project: pricingProject,
        categorize: categorizeVinylProject,
        tierNumber: project.customer_pricing?.tier_number,
      });

      const payload = {
        ...project,
        client_name: estimateContext?.client_name || project.client_name,
        customer_id: estimateContext?.customer_id || project.customer_id,
        estimate_number: estimateContext?.estimate_number || project.estimate_number,
        site_address: project.site_address || estimateContext?.site_address || "",
        workflows: cleanWorkflows,
        items: flatItems,
        customer_pricing: customerPricing || project.customer_pricing,
        status: "calculated",
        // Snapshot first workflow's vinyl/machines into the top-level fields for backward compat
        default_vinyl_id:    cleanWorkflows[0]?.vinyl_id   || "",
        default_laminate_id: cleanWorkflows[0]?.laminate_id || "",
        printer_id:    cleanWorkflows[0]?.printer_id   || "",
        cutter_id:     cleanWorkflows[0]?.cutter_id    || "",
        laminator_id:  cleanWorkflows[0]?.laminator_id || "",
        // Roll up totals
        total_print_sqft: rollup.usedSqFt,
        total_vinyl_sqft: rollup.totalRollSqFt,
        total_laminate_sqft: rollup.laminateSqFt,
        total_vinyl_cost: rollup.vinylCost,
        total_laminate_cost: rollup.laminateCost,
        total_ink_cost: rollup.inkCost,
        total_blade_cost: rollup.bladeCost,
        total_machine_cost: rollup.machineCost,
        total_personnel_cost: rollup.personnelCost,
        total_supplies_cost: rollup.supplies,
        total_equipment_cost: rollup.equipmentCost,
        base_supplies_cost: rollup.baseSupplies,
        labor_hours: rollup.laborHours,
        labor_cost: rollup.laborCost,
        subtotal: rollup.subtotal,
        markup_amount: rollup.markupAmount,
        total_cost: rollup.totalCost,
      };

      let saved;
      const activeProjectId = persistedProjectIdRef.current || projectId || "";
      if (activeProjectId) {
        saved = await updateBuilderSourceProject({
          entity: VinylProject,
          sourceId: activeProjectId,
          expectedUpdatedAt: project.updated_date,
          data: payload,
          estimateId,
          label: "Vinyl project",
        });
      } else {
        await preflightBuilderSourceMutation({ estimateId });
        const signature = JSON.stringify(payload);
        if (createAttemptRef.current.signature !== signature) {
          createAttemptRef.current = {
            signature,
            key: newCreationRequestKey("vinyl_project"),
          };
        }
        saved = await ensureIdempotentEntityCreate({
          entity: VinylProject,
          keyField: "creation_request_key",
          key: createAttemptRef.current.key,
          data: payload,
          label: "Vinyl project",
        });
        if (!saved?.id) throw new Error("Vinyl project create could not be verified.");
        persistedProjectIdRef.current = saved.id;
        if (!embedded) navigate(`/VinylEstimator?id=${saved.id}`, { replace: true });
      }

      if (estimateId && saved?.id) {
        const refreshed = await VinylProject.get(saved.id).catch(() => saved);
        // SignEstimate Pro intentionally strips transient workflow `_calc` data
        // from VinylProject records. The Builder snapshot keeps the exact calc
        // used for this save so the initial frozen BOM never has to infer today’s
        // accepted price from a later inventory state. The persisted VinylProject
        // remains source-faithful and clean.
        const builderWorkflows = (project.workflows || []).map(({ _hasIssues, ...workflow }) => workflow);
        await recordBuilderSave({
          estimateId,
          line: { project_id: saved.id, module_key: "vinyl" },
          sourceProject: { ...refreshed, workflows: builderWorkflows },
          liveTotal: rollup.totalCost,
        });
      }

      setProject(migrateProject(saved));
      onSaved?.();
      if (!embedded) alert("Estimate saved.");
    } catch (e) {
      console.error(e); alert("Save failed: " + e.message);
    }
    setSaving(false);
  };

  // #78 — clone the current save payload into a brand-new Vinyl project.
  const handleSaveAsCopy = async () => {
    if (pricingBlocked) {
      alert("Save paused: fix the flagged pricing values before saving a copy — unavailable pricing is never written as $0.");
      return;
    }
    setSaving(true);
    try {
      const cleanWorkflows = (project.workflows || []).map(({ _calc, ...rest }) => rest);
      const flatItems = cleanWorkflows.flatMap(wf =>
        (wf.items || []).map(it => ({ ...it, workflow_id: wf.id, workflow_name: wf.name }))
      );
      const copy = await saveModuleProjectCopy({
        entity: VinylProject,
        payload: {
          ...project,
          client_name: estimateContext?.client_name || project.client_name,
          customer_id: estimateContext?.customer_id || project.customer_id,
          estimate_number: estimateContext?.estimate_number || project.estimate_number,
          site_address: project.site_address || estimateContext?.site_address || "",
          workflows: cleanWorkflows,
          items: flatItems,
          customer_pricing: project.customer_pricing,
          status: "calculated",
          default_vinyl_id:    cleanWorkflows[0]?.vinyl_id   || "",
          default_laminate_id: cleanWorkflows[0]?.laminate_id || "",
          printer_id:    cleanWorkflows[0]?.printer_id   || "",
          cutter_id:     cleanWorkflows[0]?.cutter_id    || "",
          laminator_id:  cleanWorkflows[0]?.laminator_id || "",
          total_print_sqft: rollup.usedSqFt,
          total_vinyl_sqft: rollup.totalRollSqFt,
          total_laminate_sqft: rollup.laminateSqFt,
          total_vinyl_cost: rollup.vinylCost,
          total_laminate_cost: rollup.laminateCost,
          total_ink_cost: rollup.inkCost,
          total_blade_cost: rollup.bladeCost,
          total_machine_cost: rollup.machineCost,
          total_personnel_cost: rollup.personnelCost,
          total_supplies_cost: rollup.supplies,
          base_supplies_cost: rollup.baseSupplies,
          labor_hours: rollup.laborHours,
          labor_cost: rollup.laborCost,
          subtotal: rollup.subtotal,
          markup_amount: rollup.markupAmount,
          total_cost: rollup.totalCost,
        },
        attemptRef: copyAttemptRef,
        keyPrefix: "vinyl_project_copy",
        baseName: project.project_name || "Vinyl",
        label: "Vinyl project copy",
      });
      if (embedded) onSaved?.();
      else navigate(`/VinylEstimator?id=${copy.id}`);
    } catch (e) {
      console.error(e); alert("Save copy failed: " + e.message);
    }
    setSaving(false);
  };

  // #79 — template payload = the editable setup a user would reuse.
  const buildVinylTemplateData = (p) => ({
    workflows: (p.workflows || []).map(({ _calc, ...rest }) => rest),
    markup_percent: p.markup_percent,
    supplies_percent_of_materials: p.supplies_percent_of_materials,
    extra_supplies_cost: p.extra_supplies_cost,
    travel_miles_round_trip: p.travel_miles_round_trip,
    notes: p.notes,
  });

  if (loading) {
    return <div className="p-12 text-center text-slate-500"><Loader2 className="w-5 h-5 animate-spin inline mr-2" /> Loading…</div>;
  }
  if (loadError) {
    return (
      <div className="p-6 md:p-8 bg-slate-50 min-h-screen">
        <div className="max-w-2xl mx-auto rounded border border-red-200 bg-red-50 p-5 text-red-800">
          <div className="font-bold">Vinyl Builder unavailable</div>
          <div className="mt-1 text-sm">Required vinyl inventory, machine settings, installation equipment, project data, or estimate context could not be verified. Fallback configuration was not used.</div>
          <div className="mt-2 text-xs break-words">{loadError}</div>
          <Button variant="outline" className="mt-4" onClick={() => embedded ? onClose?.() : navigate(estimateId ? `/EstimateDetail?id=${estimateId}` : "/Estimator")}><ArrowLeft className="w-4 h-4 mr-2" /> Back</Button>
        </div>
      </div>
    );
  }

  const TabBtn = ({ value, icon: Icon, label, amount, warn }) => (
    <TabsTrigger value={value} className="flex items-center gap-1.5 text-xs md:text-sm py-2 data-[state=active]:bg-blue-600 data-[state=active]:text-white relative">
      <Icon className="w-4 h-4" /> <span className="truncate">{label}</span>
      {Number.isFinite(amount) && (
        <span className="ml-1 text-[10px] tabular-nums opacity-80">{fmt(amount)}</span>
      )}
      {amount === null && (
        <span className="ml-1 text-[10px] text-amber-500" title="Pricing unavailable">—</span>
      )}
      {warn && (
        <span className="absolute -top-0.5 -right-0.5 w-2 h-2 rounded-full bg-red-500 ring-2 ring-white" title="Workflow has issues" />
      )}
    </TabsTrigger>
  );

  return (
    <div className="p-6 md:p-8 bg-slate-50 min-h-screen">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-3">
          <div>
            {embedded ? (
              <button type="button" onClick={onClose} className="text-sm text-slate-500 hover:text-slate-900 inline-flex items-center gap-1">
                <ArrowLeft className="w-4 h-4" /> Back to products
              </button>
            ) : (
              <Link to={estimateId ? `/EstimateDetail?id=${estimateId}` : "/Estimator"} className="text-sm text-slate-500 hover:text-slate-900 inline-flex items-center gap-1">
                <ArrowLeft className="w-4 h-4" /> Back to estimator
              </Link>
            )}
            <h1 className="text-3xl font-bold text-slate-900 flex items-center gap-3 mt-1">
              <Droplets className="w-8 h-8 text-blue-600" />
              {projectId ? "Edit" : "New"} Vinyl Estimate
            </h1>
          </div>
          <div className="flex gap-2 flex-wrap">
            <Link to="/VinylInventory">
              <Button variant="outline"><SettingsIcon className="w-4 h-4 mr-1" /> Vinyl Inventory</Button>
            </Link>
            <Link to="/VinylSettings">
              <Button variant="outline"><SettingsIcon className="w-4 h-4 mr-1" /> Machine Settings</Button>
            </Link>
          </div>
        </div>

        <div className="grid lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2">
            <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
              <div className="sticky top-[64px] z-30 -mx-2 px-2 py-2 bg-slate-50/95 backdrop-blur-md border-b border-slate-200/60">
                <TabsList className="grid w-full bg-white shadow-md border border-slate-200 h-auto p-1 gap-1" style={{ gridTemplateColumns: "repeat(6, minmax(0, 1fr))" }}>
                  <TabBtn value="project"   icon={FileText}   label="Project" />
                  <TabBtn value="workflows" icon={Layers}     label="Vinyl Workflows" amount={sumOrNull(rollup.materialCost, rollup.machineCost, rollup.laborCost)} warn={workflowsHaveIssues || workflowPricing.some(p => p.issues.length > 0)} />
                  <TabBtn value="install"   icon={HardHat}    label="Installation"    amount={sumOrNull(rollup.equipmentCost, rollup.personnelCost)} warn={installIssue} />
                  <TabBtn value="travel"    icon={MapPin}     label="Travel"          amount={rollup.travelCost} warn={travelIssue} />
                  <TabBtn value="summary"   icon={Calculator} label="Summary"         amount={rollup.totalCost} warn={summaryIssue} />
                  <TabBtn value="pricing"   icon={TrendingUp} label="Customer Pricing" />
                </TabsList>
              </div>

              {/* Pricing-availability banner — visible on every tab so a
                  blocked save always shows why. */}
              {allIssues.length > 0 && (
                <div
                  role="status"
                  id="vinyl-pricing-issues"
                  className="mt-3 flex items-start gap-2 text-xs text-amber-900 bg-amber-50 border border-amber-300 rounded px-3 py-2"
                >
                  <AlertTriangle className="w-4 h-4 mt-0.5 flex-shrink-0 text-amber-600" />
                  <div className="min-w-0">
                    <div className="font-semibold">
                      Pricing unavailable — {allIssues.length} value{allIssues.length === 1 ? "" : "s"} need attention before this estimate can be priced or saved.
                    </div>
                    <ul className="mt-1 space-y-0.5 list-disc list-inside">
                      {allIssues.slice(0, 5).map((it, i) => <li key={i}>{it.message}</li>)}
                      {allIssues.length > 5 && <li>…and {allIssues.length - 5} more</li>}
                    </ul>
                  </div>
                </div>
              )}

              {/* PROJECT TAB */}
              <TabsContent value="project" className="mt-4 space-y-4">
                <Card className="bg-white border-0 shadow-sm">
                  <CardHeader className="pb-3"><CardTitle className="text-lg">Project Information</CardTitle></CardHeader>
                  <CardContent className="space-y-4">
                    <div className="grid md:grid-cols-2 gap-4">
                      <div>
                        <Label>Client Name *</Label>
                        <Input
                          value={estimateContext?.client_name || project.client_name || ""}
                          onChange={(e) => !embedded && updateProject({ client_name: e.target.value })}
                          readOnly={embedded}
                          className="mt-1"
                          placeholder="Enter client name"
                        />
                        {embedded && <p className="text-[10px] text-slate-400 mt-1">Inherited from the All-In-One estimate.</p>}
                      </div>
                      <div>
                        <Label>Project Name *</Label>
                        <Input value={project.project_name} onChange={(e) => updateProject({ project_name: e.target.value })} className="mt-1" />
                      </div>
                    </div>
                    <div className="grid md:grid-cols-2 gap-4">
                      <div>
                        <Label>Estimate Number</Label>
                        <Input value={estimateContext?.estimate_number || project.estimate_number || ""} onChange={(e) => !embedded && updateProject({ estimate_number: e.target.value })} readOnly={embedded} placeholder="e.g., VIN-2024-001" className="mt-1" />
                      </div>
                      <div>
                        <Label>Project Link <span className="text-xs font-normal text-slate-400">(optional)</span></Label>
                        <Input value={project.hyperlink} onChange={(e) => updateProject({ hyperlink: e.target.value })} placeholder="https://..." className="mt-1" />
                      </div>
                    </div>

                    {/* Interior / Exterior */}
                    <div>
                      <Label className="text-sm font-semibold text-slate-900">Installation Environment</Label>
                      <p className="text-xs text-slate-500 mt-1 mb-2">
                        Where is this vinyl going to live? Drives default site conditions for the install tab.
                      </p>
                      <div className="grid grid-cols-2 gap-2 max-w-md">
                        {[
                          { value: "exterior", label: "Exterior", desc: "Outdoor wall, vehicle, storefront", color: "blue" },
                          { value: "interior", label: "Interior", desc: "Lobby, indoor wall, office", color: "amber" },
                        ].map((opt) => {
                          const active = (project.install_environment || "exterior") === opt.value;
                          const ringClass = opt.color === "blue"
                            ? (active ? "border-blue-500 bg-blue-50 shadow-sm" : "border-slate-200 bg-white hover:border-slate-300")
                            : (active ? "border-amber-500 bg-amber-50 shadow-sm" : "border-slate-200 bg-white hover:border-slate-300");
                          return (
                            <button key={opt.value} type="button"
                              onClick={() => updateProject({ install_environment: opt.value })}
                              className={`text-left p-3 rounded-lg border-2 transition-all ${ringClass}`}>
                              <div className="text-sm font-semibold text-slate-800">{opt.label}</div>
                              <div className="text-[11px] text-slate-500 mt-0.5 leading-tight">{opt.desc}</div>
                            </button>
                          );
                        })}
                      </div>
                    </div>

                    {/* Site Address */}
                    <div>
                      <Label className="flex items-center gap-1.5">
                        <MapPin className="w-3.5 h-3.5 text-blue-600" />
                        Site Address
                        <span className="text-xs font-normal text-slate-500">(used for travel mileage)</span>
                      </Label>
                      <AddressAutocomplete
                        value={project.site_address || ""}
                        onChange={(val) => updateProject({ site_address: val })}
                        placeholder="e.g., 123 Main St, Cincinnati, OH 45202"
                        className="mt-1"
                      />
                    </div>
                  </CardContent>
                </Card>

                <Card className="bg-white border-0 shadow-sm">
                  <CardHeader className="pb-3"><CardTitle className="text-lg">Notes</CardTitle></CardHeader>
                  <CardContent>
                    <Textarea value={project.notes || ""} onChange={(e) => updateProject({ notes: e.target.value })} className="h-32" />
                  </CardContent>
                </Card>

                <div className="flex justify-end">
                  <Button onClick={() => setActiveTab("workflows")} className="bg-blue-600 hover:bg-blue-700 text-white">
                    Continue to Vinyl Workflows →
                  </Button>
                </div>
              </TabsContent>

              {/* WORKFLOWS TAB */}
              <TabsContent value="workflows" className="mt-4 space-y-4">
                <div className="flex items-center justify-between bg-white rounded-lg border border-slate-200 px-3 py-2 shadow-sm flex-wrap gap-2">
                  <div className="text-sm text-slate-600">
                    Add one workflow per vinyl type. Each workflow lays out on its own roll.
                  </div>
                  <div className="flex items-center gap-1 flex-wrap">
                    {project.workflows.length > 1 && (
                      <Button size="sm" variant="outline" onClick={() => setAllOpen(o => !o)} className="h-8">
                        {allOpen
                          ? <><ChevronsDownUp className="w-3.5 h-3.5 mr-1" /> Collapse All</>
                          : <><ChevronsUpDown className="w-3.5 h-3.5 mr-1" /> Expand All</>}
