                  </CardContent>
                </Card>
              </TabsContent>

              {/* SUMMARY TAB */}
              <TabsContent value="summary" className="mt-4 space-y-3">
                <Card className="bg-white border-0 shadow-sm">
                  <CardHeader className="pb-3">
                    <CardTitle className="text-lg">Cost Breakdown</CardTitle>
                  </CardHeader>
                  <CardContent className="text-sm space-y-3">
                    <BreakdownTable rollup={rollup} project={project} pricingUnavailable={pricingUnavailable} />
                  </CardContent>
                </Card>
              </TabsContent>

              {/* CUSTOMER PRICING TAB */}
              <TabsContent value="pricing" className="mt-4 space-y-3">
                <CustomerPricingTab
                  project={{
                    ...project,
                    // Feed live rollup totals so categorizer sees current numbers.
                    // Held values surface as 0 here — this tab is advisory only;
                    // the blocked save keeps them from reaching the record.
                    total_vinyl_cost:    rollup.vinylCost ?? 0,
                    total_laminate_cost: rollup.laminateCost ?? 0,
                    total_ink_cost:      rollup.inkCost ?? 0,
                    total_blade_cost:    rollup.bladeCost ?? 0,
                    total_machine_cost:  rollup.machineCost ?? 0,
                    total_supplies_cost: rollup.supplies ?? 0,
                    labor_cost:          rollup.laborCost ?? 0,
                    total_personnel_cost: rollup.personnelCost ?? 0,
                    total_equipment_cost: rollup.equipmentCost ?? 0,
                    total_travel_cost:    rollup.travelCost ?? 0,
                  }}
                  categorize={categorizeVinylProject}
                  accentColor="blue"
                  onTierChange={(tier) => setProject((prev) => ({
                    ...prev,
                    customer_pricing: { ...(prev.customer_pricing || {}), tier_number: tier },
                  }))}
                />
              </TabsContent>
            </Tabs>
          </div>

          {/* Sticky summary */}
          <div className="space-y-3">
            <VinylProjectSummaryCard
              rollup={rollup}
              project={project}
              onUpdateProject={updateProject}
              onSave={save}
              isSaving={saving}
              pricingUnavailable={pricingUnavailable}
              pricingBlocked={pricingBlocked}
              issues={allIssues}
              issuesId="vinyl-pricing-issues"
            />
            <div className="flex flex-wrap gap-2">
              <ModuleActionBar
                onTemplates={() => setTemplateMode("load")}
                onSaveAsTemplate={() => setTemplateMode("save")}
                onSaveAsCopy={handleSaveAsCopy}
                estimateId={estimateId}
                saving={saving}
              />
            </div>
          </div>
        </div>
      </div>

      {/* Workflow-tab dialogs — Features #15, #17, #31, #34 */}
      <VinylBulkImportDialog
        open={bulkOpen}
        onClose={() => setBulkOpen(false)}
        onImport={(parts) => importPartsToWorkflow(targetWorkflowIdx, parts)}
      />
      <VinylPartsLibraryDialog
        open={libraryOpen}
        onClose={() => setLibraryOpen(false)}
        onPick={(part) => addPartToWorkflow(targetWorkflowIdx, part)}
      />
      <VinylArtworkUploadDialog
        open={artworkOpen}
        onClose={() => setArtworkOpen(false)}
        onAdd={(part) => addPartToWorkflow(targetWorkflowIdx, part)}
      />
      <VinylMoveToWorkflowMenu
        open={!!moveContext}
        onClose={() => setMoveContext(null)}
        workflows={project.workflows}
        currentWorkflowIdx={moveContext?.workflowIdx ?? -1}
        onMove={(toIdx) => {
          movePart(moveContext.workflowIdx, moveContext.partIdx, toIdx);
          setMoveContext(null);
        }}
      />
      <ModuleTemplateDialog
        open={!!templateMode}
        mode={templateMode}
        onClose={() => setTemplateMode(null)}
        project={project}
        onApply={(data) => updateProject(data)}
        moduleKey="vinyl"
        title="Vinyl"
        buildTemplateData={buildVinylTemplateData}
        describeTemplate={(t) => `${(t.project_data?.workflows || []).length} workflows`}
      />
    </div>
  );
}

// Saved-fallback display: a non-finite rollup value is either the saved
// acknowledged snapshot (shown plainly) or genuinely unsaved ("Not saved").
const moneyCell = (v) => hasVinylCostSnapshot(v)
  ? fmt(v)
  : <span className="text-amber-700 font-medium">Not saved</span>;

export function BreakdownTable({ rollup, project, pricingUnavailable = false }) {
  const rows = [
    ["Vinyl", rollup.vinylCost],
    ["Laminate", rollup.laminateCost],
    ["Ink", rollup.inkCost],
    ["Blade Wear", rollup.bladeCost],
    ["Machine Time", rollup.machineCost],
    ["Labor", rollup.laborCost],
    ["Equipment", rollup.equipmentCost],
    ["Personnel", rollup.personnelCost],
    ["Travel", rollup.travelCost],
    ["Supplies", rollup.supplies],
  ];
  return (
    <div>
      {pricingUnavailable && (
        <p className="text-[11px] text-amber-800 mb-2">Saved amounts (not current pricing) — fix the flagged values to reprice.</p>
      )}
    <table className="w-full">
      <tbody>
        {rows.map(([label, value]) => (
          <tr key={label} className="border-t border-slate-100">
            <td className="py-1.5 text-slate-600">{label}</td>
            <td className="py-1.5 text-right tabular-nums">{moneyCell(value)}</td>
          </tr>
        ))}
        <tr className="border-t border-slate-200">
          <td className="py-1.5 font-semibold">Subtotal</td>
          <td className="py-1.5 text-right tabular-nums font-semibold">{moneyCell(rollup.subtotal)}</td>
        </tr>
        <tr>
          <td className="py-1.5 text-slate-600">Markup ({project.markup_percent || 0}%)</td>
          <td className="py-1.5 text-right tabular-nums">{moneyCell(rollup.markupAmount)}</td>
        </tr>
        <tr className="border-t-2 border-slate-300">
          <td className="py-2 font-bold text-base">Total</td>
          <td className="py-2 text-right tabular-nums font-bold text-base">{moneyCell(rollup.totalCost)}</td>
        </tr>
      </tbody>
    </table>
    </div>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";
import { Settings as SettingsEntity } from "@/api/gatedEntities";
import { Link } from "react-router-dom";
import { ArrowLeft, Beaker, Clock, DollarSign, Paintbrush, Plus, RotateCcw, Save, Scissors, Trash2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { saveSettingsRowsSafely } from "@/components/estimator/settings/settingsSaveGuard";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { liquidPaintRatePerSqft } from "@/components/estimator/paint/paintCalc";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";
import SettingsTransferBar from "@/components/estimator/settings/SettingsTransferBar";
import { PAINTING_SETTINGS_DEFAULTS, resetValuesToDefaults } from "@/components/estimator/settings/moduleSettingDefaults";

const PAINT_CATEGORIES = new Set(["painting_pricing", "painting_labor", "painting_supplies"]);
const UNIT_OPTIONS = ["oz", "pint", "quart", "liter", "gallon"];

const GROUPS = [
  {
    key: "rates",
    title: "Rates & Minimums",
    icon: DollarSign,
    names: ["default_labor_rate", "min_labor_hours", "min_paint_cost", "base_supplies_per_job", "default_paint_supplies_per_sqft"],
  },
  {
    key: "mix",
    title: "Paint Mix & Coverage",
    icon: Beaker,
    names: ["paint_cost_per_unit", "paint_unit", "hardener_cost_per_unit", "hardener_unit", "reducer_cost_per_unit", "reducer_unit", "paint_mix_ratio", "hardener_mix_ratio", "reducer_mix_ratio", "mixed_paint_coverage_sqft_per_gallon", "paint_waste_multiplier", "fixed_paint_waste_gallons"],
  },
  {
    key: "mask",
    title: "Paint Mask",
    icon: Scissors,
    names: ["paint_mask_rate_per_sqft", "paint_mask_machine_cutting_rate_per_sqft", "paint_mask_cutting_labor_rate_per_sqft", "paint_mask_application_labor_rate_per_sqft"],
  },
  {
    key: "labor",
    title: "Labor & Complexity",
    icon: Clock,
    names: [
      "base_labor_hours_prep_per_sqft", "base_labor_hours_paint_per_sqft", "base_labor_hours_per_sqft",
      "setup_time_labor_hours", "paint_mixing_labor_hours", "color_change_setup_hours", "paint_gun_cleaning_hours",
      "one_side_paint_multiplier", "both_sides_paint_multiplier", "additional_color_multiplier",
      "simple_complexity_multiplier", "moderate_complexity_multiplier", "complex_complexity_multiplier", "letter_perimeter_factor",
      "lettering_extra_small_prep_multiplier", "lettering_small_prep_multiplier", "lettering_normal_prep_multiplier",
      "lettering_medium_prep_multiplier", "lettering_large_prep_multiplier", "lettering_extra_large_prep_multiplier",
    ],
  },
];

const TIER_SETTINGS = [
  { key: "panel_labor_tiers", label: "Panel quantity tiers" },
  { key: "complex_shapes_labor_tiers", label: "Complex-shape quantity tiers" },
  { key: "lettering_labor_tiers", label: "Lettering quantity tiers" },
];

const parseJsonArray = (value) => {
  try {
    const parsed = JSON.parse(value || "[]");
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
};

const settingLabel = (row) => row?.description || String(row?.setting_name || "").replaceAll("_", " ");

export default function PaintingSettings() {
  const [rows, setRows] = useState([]);
  const [values, setValues] = useState({});
  const [originalValues, setOriginalValues] = useState({});
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const settingsSaveRef = useRef(false);

  useEffect(() => {
    const load = async () => {
      setLoading(true);
      try {
        const all = await loadAllEntityRows({ entity: SettingsEntity, sort: null, label: "Painting Settings catalog" });
        const paintRows = (all || []).filter((row) => PAINT_CATEGORIES.has(row.category));
        const map = Object.fromEntries(paintRows.map((row) => [row.setting_name, row.setting_value ?? ""]));
        setRows(paintRows);
        setValues(map);
        setOriginalValues(map);
      } catch (e) {
        setError(e.message || "Could not load Painting settings.");
      } finally {
        setLoading(false);
      }
    };
    load();
  }, []);

  const rowByName = useMemo(() => Object.fromEntries(rows.map((row) => [row.setting_name, row])), [rows]);
  const patch = (name, value) => setValues((prev) => ({ ...prev, [name]: String(value) }));

  useEffect(() => {
    if (loading) return;
    const prep = parseFloat(values.base_labor_hours_prep_per_sqft) || 0;
    const paint = parseFloat(values.base_labor_hours_paint_per_sqft) || 0;
    const combined = (prep + paint).toFixed(4);
    if (rowByName.base_labor_hours_per_sqft && values.base_labor_hours_per_sqft !== combined) {
      setValues((prev) => ({ ...prev, base_labor_hours_per_sqft: combined }));
    }
  }, [loading, rowByName.base_labor_hours_per_sqft, values.base_labor_hours_prep_per_sqft, values.base_labor_hours_paint_per_sqft]);

  const consumables = useMemo(() => parseJsonArray(values.paint_consumables_inventory), [values.paint_consumables_inventory]);
  const consumablesTotals = useMemo(() => consumables.reduce((acc, item) => {
    const total = (Number(item.cost) || 0) * (Number(item.qty) || 0);
    if (item.per_sqft) acc.perSqft += total;
    else acc.flat += total;
    return acc;
  }, { flat: 0, perSqft: 0 }), [consumables]);

  useEffect(() => {
    if (loading || !rowByName.paint_consumables_inventory) return;
    setValues((prev) => {
      const next = { ...prev };
      if (rowByName.base_supplies_per_job) next.base_supplies_per_job = consumablesTotals.flat.toFixed(2);
      if (rowByName.default_paint_supplies_per_sqft) next.default_paint_supplies_per_sqft = consumablesTotals.perSqft.toFixed(2);
      return next;
    });
  }, [loading, rowByName.paint_consumables_inventory, rowByName.base_supplies_per_job, rowByName.default_paint_supplies_per_sqft, consumablesTotals.flat, consumablesTotals.perSqft]);

  const liquidRate = useMemo(() => liquidPaintRatePerSqft(values), [values]);
  const coverage = Number(values.mixed_paint_coverage_sqft_per_gallon || 0);
  const mixedGallonCost = liquidRate * coverage;
  const dirtyCount = rows.filter((row) => String(values[row.setting_name] ?? "") !== String(originalValues[row.setting_name] ?? "")).length;

  const updateTier = (settingName, tierIndex, field, value) => {
    const tiers = parseJsonArray(values[settingName]);
    tiers[tierIndex] = { ...tiers[tierIndex], [field]: Number(value) };
    patch(settingName, JSON.stringify(tiers));
  };
  const addTier = (settingName) => {
    const tiers = parseJsonArray(values[settingName]);
    const previous = tiers[tiers.length - 1];
    const min = previous ? Number(previous.max_quantity || 0) + 1 : 1;
    patch(settingName, JSON.stringify([...tiers, { min_quantity: min, max_quantity: min + 9, labor_multiplier: 1 }]));
  };
  const removeTier = (settingName, index) => {
    const tiers = parseJsonArray(values[settingName]);
    const label = TIER_SETTINGS.find((tier) => tier.key === settingName)?.label || "labor tiers";
    if (!window.confirm(`Remove tier ${index + 1} from ${label}? The change applies only after you click Save.`)) return;
    patch(settingName, JSON.stringify(tiers.filter((_, i) => i !== index)));
  };

  const updateConsumable = (index, field, value) => {
    const items = [...consumables];
    items[index] = { ...items[index], [field]: field === "name" || field === "per_sqft" ? value : Number(value) };
    patch("paint_consumables_inventory", JSON.stringify(items));
  };
  const addConsumable = () => patch("paint_consumables_inventory", JSON.stringify([...consumables, { name: "New Consumable", cost: 0, qty: 1 }]));
  const removeConsumable = (index) => {
    const item = consumables[index];
    if (!window.confirm(`Remove "${item?.name || "this consumable"}" from the consumables list? The change applies only after you click Save.`)) return;
    patch("paint_consumables_inventory", JSON.stringify(consumables.filter((_, i) => i !== index)));
  };

  // #83 — stage every managed key back to the calculator's documented fallback.
  const handleResetDefaults = () => {
    setValues((prev) => resetValuesToDefaults(prev, PAINTING_SETTINGS_DEFAULTS, Object.keys(prev)));
    setMessage("Defaults staged — click Save to persist them.");
  };

  const handleSave = async () => {
    if (settingsSaveRef.current) return;
    settingsSaveRef.current = true;
    setSaving(true);
    setError("");
    setMessage("");
    try {
      const result = await saveSettingsRowsSafely({
        SettingsEntity,
        rows,
        values,
        originalValues: originalValues,
      });
      setRows(result.rows);
      setOriginalValues(result.snapshot);
      setMessage(result.changedCount ? `Saved ${result.changedCount} Painting setting${result.changedCount === 1 ? "" : "s"}.` : "No Painting settings changed.");
    } catch (e) {
      setError(e.message || "Could not save Painting settings. Admin permission may be required.");
    } finally {
      settingsSaveRef.current = false;
      setSaving(false);
    }
  };

  if (loading) return <div className="p-10 text-center text-gray-400">Loading Painting settings…</div>;

  return (
    <div className="min-h-full bg-gray-50">
      <div className="max-w-[1180px] mx-auto p-4 sm:p-5 space-y-4">
        <div className="flex items-center justify-between gap-3">
          <Link to="/EstimatorSettings" className="inline-flex items-center gap-1 text-[12px] font-semibold text-gray-600 hover:text-gray-900"><ArrowLeft className="w-4 h-4" /> Estimator Settings</Link>
          <div className="flex items-center gap-2"><SettingsTransferBar values={values} allowedKeys={Object.keys(values)} fileName="painting-settings" onImport={(imported) => setValues((v) => ({ ...v, ...imported }))} /><Button variant="outline" onClick={handleResetDefaults} disabled={saving} className="h-[32px] text-[12px] font-semibold" title="Stage calculator fallback defaults — Save to persist"><RotateCcw className="w-4 h-4 mr-1.5" /> Reset to defaults</Button><Button onClick={handleSave} disabled={saving || dirtyCount === 0} className="h-[32px] bg-[#454545] hover:bg-[#353535] text-white text-[12px] font-semibold disabled:opacity-50"><Save className="w-4 h-4 mr-1.5" /> {saving ? "Saving…" : `Save${dirtyCount ? ` (${dirtyCount})` : ""}`}</Button></div>
        </div>

        <div className="bg-white border border-gray-200 rounded-md px-4 py-3 flex items-center gap-3">
          <div className="w-9 h-9 rounded bg-sky-100 text-sky-700 flex items-center justify-center"><Paintbrush className="w-5 h-5" /></div>
          <div className="min-w-0 flex-1">
            <h1 className="text-[18px] font-bold text-gray-900">Painting Settings</h1>
            <p className="text-[10px] text-gray-500">Edits the existing migrated Painting settings used by the Painting Builder. No separate settings store is created.</p>
          </div>
          <div className="hidden md:block text-right text-[10px] text-gray-500">
            <div>Mixed paint: <span className="font-semibold text-gray-800">${mixedGallonCost.toFixed(2)}/gal</span></div>
            <div>Applied liquid rate: <span className="font-semibold text-gray-800">${liquidRate.toFixed(4)}/sf</span></div>
          </div>
        </div>

        {message && <div className="px-3 py-2 rounded border border-green-200 bg-green-50 text-[11px] text-green-700">{message}</div>}
        {error && <div className="px-3 py-2 rounded border border-red-200 bg-red-50 text-[11px] text-red-700">{error}</div>}

        <div className="grid lg:grid-cols-2 gap-4">
          {GROUPS.map((group) => {
            const Icon = group.icon;
            const groupRows = group.names.map((name) => rowByName[name]).filter(Boolean);
            if (!groupRows.length) return null;
            return (
              <section key={group.key} className="bg-white border border-gray-200 rounded-md overflow-hidden">
                <div className="px-4 py-2.5 bg-gray-50 border-b border-gray-200 flex items-center gap-2"><Icon className="w-3.5 h-3.5 text-gray-500" /><span className="text-[11px] font-bold text-gray-700 uppercase tracking-wide">{group.title}</span></div>
                <div className="divide-y divide-gray-100">
                  {groupRows.map((row) => <SettingRow key={row.id} row={row} value={values[row.setting_name] ?? ""} onChange={(value) => patch(row.setting_name, value)} readOnly={row.setting_name === "base_labor_hours_per_sqft"} />)}
                </div>
              </section>
            );
          })}
        </div>

        {rowByName.paint_consumables_inventory && (
          <section className="bg-white border border-gray-200 rounded-md overflow-hidden">
            <div className="px-4 py-2.5 bg-gray-50 border-b border-gray-200 flex items-center justify-between gap-3">
              <div><div className="text-[11px] font-bold text-gray-700 uppercase tracking-wide">Consumables</div><div className="text-[10px] text-gray-500">Flat items automatically feed Base Supplies / Job; per-sq-ft items feed Paint Application Supplies / sq ft.</div></div>
              <Button variant="outline" onClick={addConsumable} className="h-[28px] text-[10px]"><Plus className="w-3 h-3 mr-1" /> Add</Button>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-[11px]">
                <thead className="bg-white text-gray-500"><tr className="border-b border-gray-100"><th className="text-left px-3 py-2 font-semibold">Item</th><th className="text-right px-3 py-2 font-semibold w-28">Cost</th><th className="text-right px-3 py-2 font-semibold w-24">Qty</th><th className="text-center px-3 py-2 font-semibold w-28">Per sq ft</th><th className="w-10" /></tr></thead>
                <tbody>{consumables.map((item, index) => <tr key={index} className="border-b border-gray-50"><td className="px-3 py-2"><Input value={item.name || ""} onChange={(e) => updateConsumable(index, "name", e.target.value)} className="h-[28px] text-[11px]" /></td><td className="px-3 py-2"><Input type="number" step="0.01" value={item.cost ?? 0} onChange={(e) => updateConsumable(index, "cost", e.target.value)} className="h-[28px] text-[11px] text-right" /></td><td className="px-3 py-2"><Input type="number" step="0.01" value={item.qty ?? 1} onChange={(e) => updateConsumable(index, "qty", e.target.value)} className="h-[28px] text-[11px] text-right" /></td><td className="px-3 py-2 text-center"><input type="checkbox" checked={!!item.per_sqft} onChange={(e) => updateConsumable(index, "per_sqft", e.target.checked)} /></td><td className="px-2"><button type="button" onClick={() => removeConsumable(index)} className="w-7 h-7 inline-flex items-center justify-center text-red-500 hover:bg-red-50 rounded"><Trash2 className="w-3.5 h-3.5" /></button></td></tr>)}</tbody>
              </table>
            </div>
            <div className="px-4 py-2.5 bg-gray-50 border-t border-gray-100 flex flex-wrap gap-x-6 gap-y-1 text-[10px] text-gray-600"><span>Flat total: <b>${consumablesTotals.flat.toFixed(2)}/job</b></span><span>Per-sq-ft total: <b>${consumablesTotals.perSqft.toFixed(2)}/sf</b></span></div>
          </section>
        )}

        <div className="grid lg:grid-cols-3 gap-4">
          {TIER_SETTINGS.map((tierDef) => {
            const row = rowByName[tierDef.key];
            if (!row) return null;
            const tiers = parseJsonArray(values[tierDef.key]);
            return (
              <section key={tierDef.key} className="bg-white border border-gray-200 rounded-md overflow-hidden">
                <div className="px-3 py-2.5 bg-gray-50 border-b border-gray-200 flex items-center justify-between gap-2"><div className="text-[11px] font-bold text-gray-700">{tierDef.label}</div><button type="button" onClick={() => addTier(tierDef.key)} className="text-[10px] font-semibold text-sky-700">+ Tier</button></div>
                <div className="p-3 space-y-2">{tiers.map((tier, index) => <div key={index} className="grid grid-cols-[1fr_1fr_1fr_24px] gap-1.5 items-end"><MiniNumber label="Min" value={tier.min_quantity} onChange={(value) => updateTier(tierDef.key, index, "min_quantity", value)} /><MiniNumber label="Max" value={tier.max_quantity} onChange={(value) => updateTier(tierDef.key, index, "max_quantity", value)} /><MiniNumber label="Multiplier" step="0.01" value={tier.labor_multiplier} onChange={(value) => updateTier(tierDef.key, index, "labor_multiplier", value)} /><button type="button" onClick={() => removeTier(tierDef.key, index)} className="h-[28px] text-red-500 hover:bg-red-50 rounded">×</button></div>)}</div>
              </section>
            );
          })}
        </div>

        <div className="text-[10px] text-gray-400 pb-3">Loaded {rows.length} Painting-category settings. Compatibility settings not used by the current Painting Builder remain preserved in the database even when they are not shown here.</div>
      </div>
    </div>
  );
}

function SettingRow({ row, value, onChange, readOnly = false }) {
  const isUnit = ["paint_unit", "hardener_unit", "reducer_unit"].includes(row.setting_name);
  return (
    <div className="grid sm:grid-cols-[minmax(0,1fr)_150px] gap-2 px-4 py-2.5 items-center">
      <div className="min-w-0"><div className="text-[11px] font-medium text-gray-700">{settingLabel(row)}</div><div className="text-[9px] text-gray-400 font-mono mt-0.5">{row.setting_name}</div></div>
      {isUnit ? (
        <Select value={value || "gallon"} onValueChange={onChange} disabled={readOnly}><SelectTrigger className="h-[28px] text-[11px]"><SelectValue /></SelectTrigger><SelectContent>{UNIT_OPTIONS.map((unit) => <SelectItem key={unit} value={unit}>{unit}</SelectItem>)}</SelectContent></Select>
      ) : (
        <Input type={row.setting_type === "number" ? "number" : "text"} step={row.setting_type === "number" ? "0.01" : undefined} value={value} onChange={(e) => onChange(e.target.value)} readOnly={readOnly} className={`h-[28px] text-[11px] text-right ${readOnly ? "bg-gray-100 text-gray-500" : ""}`} />
      )}
    </div>
  );
}

function MiniNumber({ label, value, onChange, step = "1" }) {
  return <label className="text-[9px] text-gray-400">{label}<Input type="number" step={step} value={value ?? 0} onChange={(e) => onChange(e.target.value)} className="h-[28px] text-[10px] mt-0.5 px-2" /></label>;
}

import { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Sparkles, Loader2, Wand2, Image as ImageIcon, X, Upload } from "lucide-react";
import { base44 } from "@/api/base44Client";
import { ESTIMATOR_AI_MODEL } from "../../../base44/shared/estimatorAiModelPolicy.js";

const SCHEMA = {
  type: "object",
  properties: {
    items: {
      type: "array",
      items: {
        type: "object",
        properties: {
          description: { type: "string" },
          installation_type: {
            type: "string",
            enum: ["flush_mount", "halo_lit", "raceway", "dimensional_lettering"]
          },
          qty_letters: { type: "number" },
          letter_size: {
            type: "string",
            enum: ["extra_small", "small", "medium", "large", "extra_large", "extra_extra_large"]
          },
          letter_height_inches: { type: "number" },
          installation_height_feet: { type: "number" },
          raceway_length_feet: { type: "number" },
          wall_material: { type: "string", enum: ["eifs", "stucco", "brick", "concrete", "metal", "wood", "glass", "drywall"] },
          parapet: { type: "boolean" },
          poor_electrical_access: { type: "boolean" },
          thick_hollow_walls: { type: "boolean" },
          escort_required: { type: "boolean" },
          badging_checkin: { type: "boolean" },
          after_hours_weekend: { type: "boolean" },
          set_hours_installation: { type: "boolean" },
          poor_site_access: { type: "boolean" }
        },
        required: ["installation_type", "qty_letters"]
      }
    },
    notes: { type: "string" }
  }
};

export default function AIInstallScopeModal({ open, onClose, onApply }) {
  const [rawText, setRawText] = useState("");
  const [loading, setLoading] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [mockups, setMockups] = useState([]); // [{ url, name }]
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const [mode, setMode] = useState("append"); // "append" | "replace"

  const handleFiles = async (files) => {
    if (!files || files.length === 0) return;
    setUploading(true);
    setError(null);
    try {
      const uploaded = [];
      for (const file of Array.from(files)) {
        const { file_url } = await base44.integrations.Core.UploadFile({ file });
        uploaded.push({ url: file_url, name: file.name });
      }
      setMockups((prev) => [...prev, ...uploaded]);
    } catch (e) {
      setError(e.message || "Upload failed");
    }
    setUploading(false);
  };

  const removeMockup = (idx) => {
    setMockups((prev) => prev.filter((_, i) => i !== idx));
  };

  const canGenerate = !loading && !uploading && (rawText.trim().length > 0 || mockups.length > 0);

  const generate = async () => {
    if (!canGenerate) return;
    setLoading(true);
    setError(null);
    setResult(null);
    try {
      const hasImages = mockups.length > 0;
      const hasText = rawText.trim().length > 0;

      const imageInstructions = hasImages ? `
You've also been provided with ${mockups.length === 1 ? "a sign mockup image" : `${mockups.length} sign mockup images`}. Carefully analyze:
- Count the actual letters/characters in each mockup (don't include spaces in count)
- Estimate letter height proportions if a height isn't stated
- Identify if the sign appears to be flush-mounted, halo-lit (backlit glow), raceway-mounted (visible horizontal mounting bar behind letters), or dimensional (flat cut, non-illuminated)
- Note wall material if visible (EIFS, brick, stucco, glass, metal, etc.)
- Flag any visible site conditions (parapet wall, height obstacles, signs of difficult access)
- If multiple distinct signs appear, create a separate line item for each
${hasText ? "Use the written notes below as the primary source of truth; the image fills in gaps." : "Generate items based on what you observe in the image(s)."}` : "";

      const res = await base44.integrations.Core.InvokeLLM({
        model: ESTIMATOR_AI_MODEL,
        prompt: `You are a sign-installation estimator. Parse the input into structured installation line items.
${imageInstructions}

Map installation_type:
- "flush mount" or "face-lit" → flush_mount
- "halo lit" / "backlit" / "reverse channel" → halo_lit
- "raceway mounted" or "raceway" → raceway
- "dimensional" / "flat cut" / "pvc letters" → dimensional_lettering

Map letter_size from letter_height_inches:
- ≤6" → extra_small
- 7–12" → small
- 13–24" → medium
- 25–36" → large
- 37–60" → extra_large
- >60" → extra_extra_large

Defaults if unspecified: installation_height_feet=12, wall_material="eifs", letter_height_inches=24.
Set condition booleans (parapet, after_hours_weekend, escort_required, badging_checkin, poor_electrical_access, poor_site_access, set_hours_installation, thick_hollow_walls) to true ONLY if clearly mentioned or visible. For raceway items also set raceway_length_feet.

${hasText ? `JOB DESCRIPTION / NOTES:
${rawText}` : "(No written notes — rely entirely on the mockup image(s).)"}`,
        ...(hasImages ? { file_urls: mockups.map(m => m.url) } : {}),
        response_json_schema: SCHEMA
      });
      setResult(res);
    } catch (e) {
      setError(e.message || "Generation failed");
    }
    setLoading(false);
  };

  const apply = () => {
    if (!result?.items?.length) return;
    if (mode === "replace" && !confirm("Replace all existing line items with the AI-generated items?")) return;
    onApply(result.items, mode);
    setRawText("");
    setMockups([]);
    setResult(null);
    onClose();
  };

  const conditionFlags = (it) => {
    const flags = [];
    if (it.parapet) flags.push("parapet");
    if (it.after_hours_weekend) flags.push("after hours");
    if (it.escort_required) flags.push("escort");
    if (it.badging_checkin) flags.push("badging");
    if (it.poor_electrical_access) flags.push("poor electrical");
    if (it.poor_site_access) flags.push("poor access");
    if (it.set_hours_installation) flags.push("set hours");
    if (it.thick_hollow_walls) flags.push("thick walls");
    return flags;
  };

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Sparkles className="w-5 h-5 text-purple-600" />
            AI Scope Writer — Installation
          </DialogTitle>
          <p className="text-xs text-slate-500">Paste rough install notes and/or upload a sign mockup — AI will extract structured line items with site conditions.</p>
        </DialogHeader>

        <div className="space-y-3">
          {/* Mockup uploader */}
          <div>
            <label className="flex items-center justify-between text-xs font-medium text-slate-700 mb-1.5">
              <span className="flex items-center gap-1.5">
                <ImageIcon className="w-3.5 h-3.5 text-purple-600" />
                Sign Mockups <span className="text-slate-400 font-normal">(optional — drag in or click to add)</span>
              </span>
              {mockups.length > 0 && (
                <span className="text-[10px] text-purple-700 bg-purple-50 border border-purple-200 rounded px-1.5 py-0.5">
                  {mockups.length} attached
                </span>
              )}
            </label>

            <label
              htmlFor="ai-scope-mockup-input"
              className={`relative flex flex-col items-center justify-center w-full border-2 border-dashed rounded-lg cursor-pointer transition-colors ${
                uploading ? "bg-purple-50 border-purple-300" : "bg-slate-50/60 border-slate-300 hover:bg-purple-50/60 hover:border-purple-300"
              } ${mockups.length === 0 ? "py-5" : "py-3"}`}
              onDragOver={(e) => e.preventDefault()}
              onDrop={(e) => {
                e.preventDefault();
                handleFiles(e.dataTransfer.files);
              }}
            >
              <input
                id="ai-scope-mockup-input"
                type="file"
                accept="image/*"
                multiple
                className="hidden"
                onChange={(e) => handleFiles(e.target.files)}
                disabled={uploading || loading}
              />
              {uploading ? (
                <span className="text-xs text-purple-700 inline-flex items-center gap-2"><Loader2 className="w-3.5 h-3.5 animate-spin" /> Uploading...</span>
              ) : (
                <span className="text-xs text-slate-600 inline-flex items-center gap-2">
                  <Upload className="w-3.5 h-3.5 text-purple-600" />
                  Drop sign mockup(s) here, or click to browse
                </span>
              )}
            </label>

            {mockups.length > 0 && (
              <div className="mt-2 grid grid-cols-3 sm:grid-cols-4 gap-2">
                {mockups.map((m, i) => (
                  <div key={i} className="relative group bg-white border border-slate-200 rounded-md overflow-hidden">
                    <img src={m.url} alt={m.name} className="w-full h-24 object-contain bg-slate-50" />
                    <button
                      type="button"
                      onClick={() => removeMockup(i)}
                      className="absolute top-1 right-1 bg-white/90 hover:bg-red-50 border border-slate-200 rounded p-0.5 shadow-sm"
                      title="Remove"
                    >
                      <X className="w-3 h-3 text-red-600" />
                    </button>
                    <div className="text-[10px] text-slate-500 truncate px-1.5 py-0.5 bg-white border-t border-slate-100" title={m.name}>{m.name}</div>
                  </div>
                ))}
              </div>
            )}
          </div>

          <Textarea
            value={rawText}
            onChange={(e) => setRawText(e.target.value)}
            placeholder={`Example:\n"Install 12 channel letters at 18ft on EIFS, halo lit, 24" tall. After hours work, parapet wall, escort required. Also 1 raceway-mounted set, 10ft long, at 14ft."\n\nOr leave blank and just upload a mockup above.`}
            className="h-32 text-sm"
            disabled={loading}
          />

          {error && (
            <div className="text-xs text-red-700 bg-red-50 border border-red-200 rounded p-2">{error}</div>
          )}

          {result?.items?.length > 0 && (
            <div className="border border-purple-200 bg-purple-50/40 rounded-lg p-3 space-y-2 max-h-72 overflow-y-auto">
              <div className="text-xs font-semibold text-purple-900 flex items-center gap-1">
                <Wand2 className="w-3.5 h-3.5" />
                AI generated {result.items.length} item{result.items.length !== 1 ? "s" : ""}:
              </div>
              <div className="space-y-1.5">
                {result.items.map((it, i) => (
                  <div key={i} className="bg-white rounded border border-purple-100 px-2 py-1.5 text-xs space-y-1">
                    <div className="flex items-center gap-2 flex-wrap">
                      <Badge variant="outline" className="bg-purple-100 text-purple-800 border-purple-200 text-[10px]">
                        {it.installation_type?.replace(/_/g, " ")}
                      </Badge>
                      <span className="font-semibold">{it.qty_letters}×</span>
                      {it.letter_height_inches > 0 && <span className="text-slate-600">{it.letter_height_inches}"</span>}
                      {it.installation_height_feet > 0 && <span className="text-slate-500">@ {it.installation_height_feet}ft</span>}
                      {it.wall_material && <span className="text-slate-500">on {it.wall_material}</span>}
                      {it.raceway_length_feet > 0 && <span className="text-slate-500">· {it.raceway_length_feet}ft raceway</span>}
                    </div>
                    {it.description && <div className="text-slate-600 italic">{it.description}</div>}
                    {conditionFlags(it).length > 0 && (
                      <div className="flex flex-wrap gap-1">
                        {conditionFlags(it).map((f) => (
                          <span key={f} className="text-[10px] bg-amber-100 text-amber-800 border border-amber-200 rounded px-1.5 py-0.5">
                            {f}
                          </span>
                        ))}
                      </div>
                    )}
                  </div>
                ))}
              </div>
              {result.notes && (
                <div className="text-[11px] text-slate-600 italic border-t border-purple-200 pt-1.5">
                  <strong>AI notes:</strong> {result.notes}
                </div>
              )}
            </div>
          )}
        </div>

        <DialogFooter className="gap-2 sm:justify-between flex-wrap">
          {result ? (
            <div className="inline-flex rounded-lg border border-slate-200 bg-slate-50 p-0.5 text-xs">
              <button
                type="button"
                onClick={() => setMode("append")}
                className={`px-2.5 py-1 rounded-md font-medium transition-colors ${mode === "append" ? "bg-white text-slate-900 shadow-sm" : "text-slate-500 hover:text-slate-700"}`}
              >
                Append
              </button>
              <button
                type="button"
                onClick={() => setMode("replace")}
                className={`px-2.5 py-1 rounded-md font-medium transition-colors ${mode === "replace" ? "bg-white text-red-700 shadow-sm" : "text-slate-500 hover:text-slate-700"}`}
              >
                Clear & Replace
              </button>
            </div>
          ) : <div />}
          <div className="flex gap-2">
            <Button variant="outline" onClick={onClose} disabled={loading}>Cancel</Button>
            {!result ? (
              <Button onClick={generate} disabled={!canGenerate} className="bg-purple-600 hover:bg-purple-700 text-white">
                {loading ? <><Loader2 className="w-4 h-4 mr-2 animate-spin" /> Generating...</> : <><Sparkles className="w-4 h-4 mr-2" /> Generate Items</>}
              </Button>
            ) : (
              <Button onClick={apply} className={mode === "replace" ? "bg-red-600 hover:bg-red-700 text-white" : "bg-green-600 hover:bg-green-700 text-white"}>
                <Wand2 className="w-4 h-4 mr-2" /> {mode === "replace" ? "Replace All Items" : "Add to Estimate"}
              </Button>
            )}
          </div>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Sparkles, Loader2, Wand2 } from "lucide-react";
import { base44 } from "@/api/base44Client";
import { ESTIMATOR_AI_MODEL } from "../../../base44/shared/estimatorAiModelPolicy.js";

const SCHEMA = {
  type: "object",
  properties: {
    letter_purchases: {
      type: "array",
      items: {
        type: "object",
        properties: {
          letter_type: {
            type: "string",
            enum: ["raceway", "channel_raceway_mounted", "channel_flush_mounted", "channel_halo_lit", "capsule_logo_pillbox", "dimensional_letters"]
          },
          description: { type: "string" },
          qty: { type: "number" },
          size_value: { type: "number", description: "Vertical inches for channel letters, linear feet for raceway, sq ft for capsule/dimensional" },
          install_height_feet: { type: "number" },
          wall_material: { type: "string", enum: ["eifs", "stucco", "brick", "concrete", "metal", "wood", "glass", "drywall"] }
        },
        required: ["letter_type", "qty"]
      }
    },
    notes: { type: "string", description: "Brief summary of what was inferred and any assumptions made" }
  }
};

export default function AIScopeWriterModal({ open, onClose, onApply }) {
  const [rawText, setRawText] = useState("");
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const [mode, setMode] = useState("append"); // "append" | "replace"

  const generate = async () => {
    if (!rawText.trim()) return;
    setLoading(true);
    setError(null);
    setResult(null);
    try {
      const res = await base44.integrations.Core.InvokeLLM({
        model: ESTIMATOR_AI_MODEL,
        prompt: `You are a sign-shop estimator. Parse the following rough client request into structured channel letter purchase line items.

Map letter types as follows:
- "flush mount" or "face-lit" → channel_flush_mounted
- "halo lit" or "backlit" or "reverse channel" → channel_halo_lit
- "raceway mounted" → channel_raceway_mounted
- just "raceway" (no letters) → raceway
- "dimensional" or "flat cut" or "pvc letters" → dimensional_letters
- "logo" or "capsule" or "pillbox" → capsule_logo_pillbox

For size_value: use vertical inches for channel letters (e.g. "24 inch letters" → 24), linear feet for raceway, square feet for capsule/dimensional.
Default install_height_feet to 12 if not mentioned. Default wall_material to "eifs" if not mentioned.

CLIENT REQUEST:
${rawText}`,
        response_json_schema: SCHEMA
      });
      setResult(res);
    } catch (e) {
      setError(e.message || "Generation failed");
    }
    setLoading(false);
  };

  const apply = () => {
    if (!result?.letter_purchases?.length) return;
    if (mode === "replace" && !confirm("Replace all existing letter rows with the AI-generated items?")) return;
    onApply(result.letter_purchases, mode);
    setRawText("");
    setResult(null);
    onClose();
  };

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Sparkles className="w-5 h-5 text-purple-600" />
            AI Scope Writer
          </DialogTitle>
          <p className="text-xs text-slate-500">Paste rough client notes — AI will extract structured letter line items.</p>
        </DialogHeader>

        <div className="space-y-3">
          <Textarea
            value={rawText}
            onChange={(e) => setRawText(e.target.value)}
            placeholder={`Example:\n"Customer wants 12 halo-lit channel letters, 18 inches tall, mounted to a brick wall about 15 feet up. Also need a 10ft raceway."`}
            className="h-32 text-sm"
            disabled={loading}
          />

          {error && (
