              className={`flex-1 ${direction === "up" ? "bg-red-600 hover:bg-red-700" : ""}`}
            >
              <TrendingUp className="w-4 h-4 mr-1" /> Increase
            </Button>
            <Button
              type="button"
              variant={direction === "down" ? "default" : "outline"}
