import React from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { AlertTriangle } from "lucide-react";

// A clean, centered, branded confirm/alert modal that replaces native
// browser confirm()/alert() popups.
//
// Props:
//   open, onClose       — controlled visibility
//   title               — heading text
//   description         — body text (optional)
//   confirmLabel        — primary button label (default "OK")
//   cancelLabel         — secondary button label (default null, hides it)
//   tone                — "warning" | "danger" | "info" (default "warning")
//   onConfirm           — handler for the primary button
export default function ConfirmModal({
  open,
  onClose,
  title,
  description,
  confirmLabel = "OK",
  cancelLabel,
  tone = "warning",
  onConfirm,
}) {
  const toneStyles = {
    warning: { iconBg: "bg-amber-100", iconColor: "text-amber-600", btn: "bg-amber-600 hover:bg-amber-700" },
    danger:  { iconBg: "bg-red-100",   iconColor: "text-red-600",   btn: "bg-red-600 hover:bg-red-700" },
    info:    { iconBg: "bg-blue-100",  iconColor: "text-blue-600",  btn: "bg-blue-600 hover:bg-blue-700" },
  }[tone] || {};

  const handleConfirm = () => {
    if (onConfirm) onConfirm();
    onClose?.();
  };

  return (
    <Dialog open={open} onOpenChange={(v) => { if (!v) onClose?.(); }}>
      <DialogContent className="sm:max-w-md rounded-2xl">
        <DialogHeader>
          <div className="flex items-start gap-3">
            <div className={`w-10 h-10 rounded-full ${toneStyles.iconBg} flex items-center justify-center flex-shrink-0`}>
              <AlertTriangle className={`w-5 h-5 ${toneStyles.iconColor}`} />
            </div>
            <div className="flex-1 pt-1">
              <DialogTitle className="text-base font-semibold text-slate-900 text-left">{title}</DialogTitle>
              {description && (
                <DialogDescription className="text-sm text-slate-600 text-left mt-1.5 leading-relaxed">
                  {description}
                </DialogDescription>
              )}
            </div>
          </div>
        </DialogHeader>
        <DialogFooter className="gap-2 sm:gap-2 pt-2">
          {cancelLabel && (
            <Button variant="outline" onClick={onClose} className="rounded-xl">
              {cancelLabel}
            </Button>
          )}
          <Button onClick={handleConfirm} className={`text-white rounded-xl ${toneStyles.btn}`}>
            {confirmLabel}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import React from "react";

// Compact horizontal stacked bar showing where money is going.
// Supports two APIs:
//   1. <CostBreakdownBar labor={...} materials={...} />  (legacy, used by InstallLineItem)
//   2. <CostBreakdownBar segments={[{label, value, color}]} />  (new)
export default function CostBreakdownBar({ segments, labor, materials }) {
  let segs = segments;
  let dark = true;

  // Legacy mode: build segments from labor/materials and render light-mode
  if (!segs && (labor != null || materials != null)) {
    segs = [
      { label: "Labor",     value: labor || 0,     color: "bg-purple-400" },
      { label: "Materials", value: materials || 0, color: "bg-emerald-400" },
    ];
    dark = false;
  }

  segs = segs || [];
  const total = segs.reduce((s, x) => s + (parseFloat(x.value) || 0), 0);
  const trackClass = dark ? "bg-white/10" : "bg-slate-100";
  const legendClass = dark ? "text-slate-300" : "text-slate-500";

  if (total <= 0) {
    return <div className={`h-2 w-full rounded-full ${trackClass}`} />;
  }

  return (
    <div className="space-y-1.5">
      <div className={`h-2 w-full rounded-full ${trackClass} overflow-hidden flex`}>
        {segs.map((s, i) => {
          const v = parseFloat(s.value) || 0;
          if (v <= 0) return null;
          const pct = (v / total) * 100;
          return (
            <div
              key={i}
              className={`${s.color} transition-all`}
              style={{ width: `${pct}%` }}
              title={`${s.label}: ${pct.toFixed(0)}%`}
            />
          );
        })}
      </div>
      <div className={`flex flex-wrap gap-x-3 gap-y-0.5 text-[10px] ${legendClass}`}>
        {segs
          .filter((s) => (parseFloat(s.value) || 0) > 0)
          .map((s, i) => {
            const pct = ((parseFloat(s.value) || 0) / total) * 100;
            return (
              <span key={i} className="inline-flex items-center gap-1">
                <span className={`w-1.5 h-1.5 rounded-full ${s.color}`} />
                {s.label} {pct.toFixed(0)}%
              </span>
            );
          })}
      </div>
    </div>
  );
}

import React from "react";
import { Users, HardHat, AlertTriangle } from "lucide-react";

// Suggest crew size and equipment based on max install height across items
export default function CrewEquipmentHint({ items = [] }) {
  if (!items.length) return null;

  const maxHeight = items.reduce(
    (max, it) => Math.max(max, parseFloat(it.installation_height_feet) || 0),
    0
  );
  const totalLetters = items.reduce(
    (s, it) => s + (parseFloat(it.qty_letters) || 0),
    0
  );

  let crewSize = 2;
  let equipment = "Standard ladder";
  let equipmentLevel = "low";

  if (maxHeight > 30) {
    crewSize = 4;
    equipment = "Boom lift (40ft+) + ground crew";
    equipmentLevel = "high";
  } else if (maxHeight > 20) {
    crewSize = 3;
    equipment = "Scissor lift / boom lift (30ft)";
    equipmentLevel = "medium";
  } else if (maxHeight > 12) {
    crewSize = 2;
    equipment = "Scissor lift or extension ladder (20ft)";
    equipmentLevel = "medium";
  }

  if (totalLetters > 30 && crewSize < 3) crewSize += 1;

  const levelColor = {
    low: "bg-green-50 border-green-200 text-green-900",
    medium: "bg-amber-50 border-amber-200 text-amber-900",
    high: "bg-red-50 border-red-200 text-red-900",
  }[equipmentLevel];

  return (
    <div className={`rounded-lg border p-3 ${levelColor}`}>
      <div className="flex items-center gap-2 mb-2 text-xs font-semibold uppercase tracking-wide">
        <HardHat className="w-3.5 h-3.5" />
        Crew & Equipment Hint
      </div>
      <div className="space-y-1 text-xs">
        <div className="flex items-center gap-1.5">
          <Users className="w-3 h-3" />
          <span><strong>{crewSize}-person crew</strong> recommended</span>
        </div>
        <div className="flex items-start gap-1.5">
          <AlertTriangle className="w-3 h-3 mt-0.5" />
          <span><strong>{equipment}</strong> (max {maxHeight}ft)</span>
        </div>
      </div>
    </div>
  );
}

