// Auto-build pricing for Dimensional Letters: Material + (CNC or Laser) + Paint.
// IMPORTANT: This file mirrors the EXACT calculation logic used by the
// stand-alone CNC, Laser, and Paint estimators, so changing settings in
// CNCSettings / LaserSettings / PaintSettings flows through here identically.
//
// Pure functions — no React, no entity calls.

const num = (v, fb = 0) => {
  const n = parseFloat(v);
  return isNaN(n) ? fb : n;
};

// Default fab config for a brand-new dimensional letter row
export const emptyFabConfig = () => ({
  material_id: null,
  material_name: "",
  material_thickness_inches: 0.5,
  material_cost_per_sqin: 0,
  sheet_yield_factor: 0.7,

  // Letter geometry
  letter_height_inches: 0,
  letter_width_inches: 0,
  letter_perimeter_inches: 0,

  // Cutting method
  cutting_method: "cnc", // "cnc" | "laser"

  // Cut params (auto-seeded from settings; overridable)
  cut_speed_ipm: 50,
  cut_multiplier: 1.0,

  // Paint params — same shape as the stand-alone Paint estimator items
  paint_letters: true,
  paint_sides: "front_and_edges", // none | front | front_and_edges | all
  num_paint_colors: 1,
  paint_colors: [],
  paint_mask_sqft: 0,
  approx_coverage_factor: "1/4",

  // Resolved cost breakdown (filled by calculator)
  unit_material_cost: 0,
  unit_cut_cost: 0,
  unit_paint_cost: 0,
  unit_total_cost: 0,
});

// ============================================================================
// Geometry helpers
// ============================================================================

// Letter perimeter — matches the stand-alone CNC estimator:
//   cutLength = letter_height * cnc_letter_perimeter_factor * num_letters
// We compute per-letter here (num_letters is applied at the row level).
const estimatePerimeterPerLetter = (h, settings, cuttingMethod, override) => {
  if (num(override) > 0) return num(override);
  const factorKey = cuttingMethod === "laser"
    ? "laser_letter_perimeter_factor"
    : "cnc_letter_perimeter_factor";
  const factor = num(settings[factorKey], 3.5);
  return num(h) * factor;
};

// Letter face area — matches the stand-alone Paint estimator's lettering case:
//   faceArea = letterHeight^2 * 0.8 * numLetters / 144  (sqft)
// We compute per-letter in sqin here so it composes with cutting math.
const estimateFaceAreaSqinPerLetter = (h) => {
  return Math.pow(num(h), 2) * 0.8;
};

// ============================================================================
// Rate accessors (mirror the stand-alone estimators exactly)
// ============================================================================

export const getCncRates = (settings) => ({
  machine_rate: num(settings.cnc_machine_rate, 75),
  labor_rate: num(settings.cnc_labor_rate, 45),
  setup_time_percentage: num(settings.cnc_setup_time_percentage, 20),
  min_setup_hours: num(settings.min_cnc_setup_hours, 0),
  min_labor_hours: num(settings.min_cnc_labor_hours, 0),
  letter_perimeter_factor: num(settings.cnc_letter_perimeter_factor, 3.5),
});

export const getLaserRates = (settings) => ({
  machine_rate: num(settings.parameter_laser_machine_rate, 100),
  labor_rate: num(settings.parameter_laser_labor_rate, 45),
  // Laser uses "handling time percentage" instead of "setup time percentage"
  setup_time_percentage: num(settings.parameter_handling_time_percentage, 15),
  min_setup_hours: num(settings.min_laser_setup_hours, 0),
  min_labor_hours: num(settings.min_laser_labor_hours, 0),
  letter_perimeter_factor: num(settings.laser_letter_perimeter_factor, 3.5),
});

export const getActiveRates = (cuttingMethod, settings) =>
  cuttingMethod === "laser" ? getLaserRates(settings) : getCncRates(settings);

// Mixed liquid paint $/sqft — uses the EXACT Paint estimator formula.
const computeLiquidPaintPerSqft = (settings) => {
  const unitFactors = { oz: 128, pint: 8, quart: 4, liter: 3.78541, gallon: 1 };
  const perGallon = (cost, unit) => {
    const c = num(cost);
    const f = unitFactors[unit] || 1;
    return c * f;
  };
  const paintG = perGallon(settings.paint_cost_per_unit, settings.paint_unit);
  const hardG = perGallon(settings.hardener_cost_per_unit, settings.hardener_unit);
  const redG = perGallon(settings.reducer_cost_per_unit, settings.reducer_unit);

  const pR = num(settings.paint_mix_ratio, 3);
  const hR = num(settings.hardener_mix_ratio, 1);
  const rR = num(settings.reducer_mix_ratio, 1);
  const total = pR + hR + rR;
  if (total === 0) return 0;
  const costPerMixedGallon =
    (paintG / total) * pR + (hardG / total) * hR + (redG / total) * rR;
  const coverage = num(settings.mixed_paint_coverage_sqft_per_gallon, 350);
  return coverage > 0 ? costPerMixedGallon / coverage : 0;
};

export const getPaintRates = (settings) => ({
  labor_rate: num(settings.default_labor_rate, 60),
  supplies_per_sqft: num(settings.default_paint_supplies_per_sqft, 1.25),
  liquid_paint_per_sqft: computeLiquidPaintPerSqft(settings),
  waste_multiplier: num(settings.paint_waste_multiplier, 1.25),
  coverage_sqft_per_gallon: num(settings.mixed_paint_coverage_sqft_per_gallon, 350),
  base_hours_per_sqft: num(settings.base_labor_hours_per_sqft, 0.05),
  min_labor_hours: num(settings.min_labor_hours, 0),
  min_paint_cost: num(settings.min_paint_cost, 0),
  mixing_hours_per_gallon: num(settings.paint_mixing_labor_hours, 0.25),
  setup_hours: num(settings.setup_time_labor_hours, 0.5),
  color_change_setup_hours: num(settings.color_change_setup_hours, 0.25),
  paint_gun_cleaning_hours: num(settings.paint_gun_cleaning_hours, 0.15),
  // Mask rates
  mask_material_rate: num(settings.paint_mask_rate_per_sqft, 0.75),
  mask_machine_rate: num(settings.paint_mask_machine_cutting_rate_per_sqft, 0.1),
  mask_application_labor_rate: num(settings.paint_mask_application_labor_rate_per_sqft, 0.25),
  mask_cutting_labor_rate: num(settings.paint_mask_cutting_labor_rate_per_sqft, 0.15),
  // Multipliers — letter complexity defaults to "complex" for dimensional letters
  // since they're not rectangular panels (matches Paint estimator behavior).
  complex_multiplier: num(settings.complex_complexity_multiplier, 1.5),
  moderate_multiplier: num(settings.moderate_complexity_multiplier, 1.0),
  one_side_multiplier: num(settings.one_side_paint_multiplier, 0.8),
  both_sides_multiplier: num(settings.both_sides_paint_multiplier, 1.0),
  additional_color_multiplier: num(settings.additional_color_multiplier, 0.3),
});

// ============================================================================
// Main cost calculator — matches the stand-alone estimator math
// ============================================================================
//
// `qty` here = number of letters in the row (not a separate quantity multiplier).
// Returns PER-LETTER costs for the breakdown UI, plus row-level totals so the
// estimator can apply minimums against the whole row (just like the stand-alone
// estimators do at the project level).
export const calcDimensionalUnitCost = (fab, qty, settings) => {
  const safe = { ...emptyFabConfig(), ...fab };
  const numLetters = Math.max(1, num(qty, 1));

  // === 1) Material cost per letter ===
  const facePerLetterSqin = estimateFaceAreaSqinPerLetter(safe.letter_height_inches);
  const unit_material_cost = facePerLetterSqin * num(safe.material_cost_per_sqin);

  // === 2) Cutting cost — uses stand-alone CNC/Laser math ===
  const rates = getActiveRates(safe.cutting_method, settings);
  const perLetterCutLengthIn = estimatePerimeterPerLetter(
    safe.letter_height_inches,
    settings,
    safe.cutting_method,
    safe.letter_perimeter_inches
  );
  const totalCutLengthIn = perLetterCutLengthIn * numLetters;
  const cutSpeed = Math.max(1, num(safe.cut_speed_ipm, 50));
  const cutMultiplier = Math.max(0.01, num(safe.cut_multiplier, 1));

  // Same machine-time formula as NewCNCEstimate / NewLaserEstimate:
  //   machine_time_hours = (cutLength / cutSpeed * cutMultiplier) / 60
  // (For dimensional letters we run multiple letters; cutLength is per-row.)
  const cutTimeMinutes = (totalCutLengthIn / cutSpeed) * cutMultiplier;
  const machineTimeHours = cutTimeMinutes / 60;

  // Setup/handling time = machineTime * (setup_time_percentage / 100)
  // Floor it at min_setup_hours if set in settings.
  let setupTimeHours = machineTimeHours * (rates.setup_time_percentage / 100);
  if (rates.min_setup_hours > 0 && setupTimeHours < rates.min_setup_hours) {
    setupTimeHours = rates.min_setup_hours;
  }

  let machineCost = machineTimeHours * rates.machine_rate;
  let cutLaborCost = setupTimeHours * rates.labor_rate;

  // Apply minimum-labor-hours floor on the cut labor only (matches CNC estimator).
  if (rates.min_labor_hours > 0 && setupTimeHours > 0 && setupTimeHours < rates.min_labor_hours) {
    cutLaborCost = rates.min_labor_hours * rates.labor_rate;
  }

  const totalCutCost = machineCost + cutLaborCost;
  // Per-letter slice for the breakdown UI
  const unit_cut_cost = totalCutCost / numLetters;

  // === 3) Paint cost — uses stand-alone Paint estimator math ===
  let unit_paint_cost = 0;
  let totalPaintMaskCost = 0;
  let totalLiquidPaintAndSuppliesCost = 0;
  let totalPaintLaborCost = 0;
  let totalPaintGallons = 0;

  if (safe.paint_letters && safe.paint_sides !== "none") {
    const paint = getPaintRates(settings);

    // Paintable area — match Paint estimator's lettering case:
    //   faceArea = h^2 * 0.8 * numLetters / 144   (sqft)
    //   edgeArea = h * perimFactor * numLetters * thickness / 144
    //   one_side  -> face + edges
    //   both_sides -> face*2 + edges
    const totalFaceSqft = (facePerLetterSqin * numLetters) / 144;
    const thickness = num(safe.material_thickness_inches, 0.5);
    const totalEdgeSqft = (totalCutLengthIn * thickness) / 144;

    let paintableSqft = 0;
    let paintSidesKey = "one_side"; // for stand-alone multipliers map
    if (safe.paint_sides === "front") {
      paintableSqft = totalFaceSqft;
      paintSidesKey = "one_side";
    } else if (safe.paint_sides === "front_and_edges") {
      paintableSqft = totalFaceSqft + totalEdgeSqft;
      paintSidesKey = "one_side";
    } else if (safe.paint_sides === "all") {
      paintableSqft = totalFaceSqft * 2 + totalEdgeSqft;
      paintSidesKey = "both_sides";
    }

    const colors = Array.isArray(safe.paint_colors)
      ? safe.paint_colors.filter((c) => c && c.trim() !== "")
      : [];
    const numColors = Math.max(1, colors.length || num(safe.num_paint_colors, 1));

    // -- Paint mask (multi-color only) --
    if (numColors > 1 && num(safe.paint_mask_sqft) > 0) {
      const maskMaterial = num(safe.paint_mask_sqft) * paint.mask_material_rate * (numColors - 1);
      const maskMachine = num(safe.paint_mask_sqft) * paint.mask_machine_rate * (numColors - 1);
      totalPaintMaskCost = maskMaterial + maskMachine;
    }

    // -- Liquid paint + application supplies --
    const paintApplicationSupplies = paintableSqft * paint.supplies_per_sqft * numColors;
    const liquidPaint = paintableSqft * paint.liquid_paint_per_sqft * paint.waste_multiplier * numColors;
    totalLiquidPaintAndSuppliesCost = paintApplicationSupplies + liquidPaint;

    if (paint.coverage_sqft_per_gallon > 0) {
      totalPaintGallons =
        (paintableSqft * paint.waste_multiplier * numColors) / paint.coverage_sqft_per_gallon;
    }

    // -- Item labor (matches Paint estimator's per-item labor) --
    // Dimensional letters → "complex" complexity (small/extra_small map to complex
    // in the Paint estimator; we use complex as the default for dimensional letters).
    const complexityMult = paint.complex_multiplier;
    const sidesMult =
      paintSidesKey === "both_sides" ? paint.both_sides_multiplier : paint.one_side_multiplier;

    let baseHours = paintableSqft * paint.base_hours_per_sqft * complexityMult * sidesMult;
    if (numColors > 1) {
      baseHours *= 1 + (numColors - 1) * paint.additional_color_multiplier;
    }

    // Mask application/cutting labor adds to base hours (matches Paint estimator)
    if (numColors > 1 && num(safe.paint_mask_sqft) > 0) {
      const maskApplyHrs =
        (num(safe.paint_mask_sqft) * paint.mask_application_labor_rate * (numColors - 1)) /
        paint.labor_rate;
      const maskCutHrs =
        (num(safe.paint_mask_sqft) * paint.mask_cutting_labor_rate * (numColors - 1)) /
        paint.labor_rate;
      baseHours += maskApplyHrs + maskCutHrs;
    }

    let paintLaborHours = baseHours;

    // -- Fixed labor (mixing + setup + color change + gun cleaning) --
    // Matches the Paint estimator's project-level fixed labor block.
    const numberOfMixes = Math.max(1, Math.ceil(totalPaintGallons));
    const mixingHrs = numberOfMixes * paint.mixing_hours_per_gallon;
    const setupHrs = paint.setup_hours;

    // Unique colors → drives color-change + gun-cleaning hours
    const uniqueColors = new Set(
      colors.map((c) => c.trim().toLowerCase()).filter((c) => c)
    );
    const uniqueColorCount = Math.max(numColors > 1 ? uniqueColors.size : 1, 1);
    const colorChangeHrs =
      uniqueColorCount > 1 ? (uniqueColorCount - 1) * paint.color_change_setup_hours : 0;
    const gunCleanHrs = uniqueColorCount * paint.paint_gun_cleaning_hours;

    const totalPaintLaborHrs = paintLaborHours + mixingHrs + setupHrs + colorChangeHrs + gunCleanHrs;

    // Apply min_labor_hours floor (Paint estimator's behavior)
    const effectivePaintLaborHrs =
      paint.min_labor_hours > 0 && totalPaintLaborHrs < paint.min_labor_hours
        ? paint.min_labor_hours
        : totalPaintLaborHrs;

    totalPaintLaborCost = effectivePaintLaborHrs * paint.labor_rate;

    // Apply min_paint_cost floor (Paint estimator's behavior)
    if (paint.min_paint_cost > 0 && totalLiquidPaintAndSuppliesCost < paint.min_paint_cost) {
      totalLiquidPaintAndSuppliesCost = paint.min_paint_cost;
    }

    const totalPaint = totalPaintMaskCost + totalLiquidPaintAndSuppliesCost + totalPaintLaborCost;
    unit_paint_cost = totalPaint / numLetters;
  }

  const unit_total_cost = unit_material_cost + unit_cut_cost + unit_paint_cost;

  return {
    ...safe,
    face_area_sqin: facePerLetterSqin,
    cut_length_inches: perLetterCutLengthIn,
    // Per-letter values (used by the on-row breakdown UI)
    unit_material_cost,
    unit_cut_cost,
    unit_cnc_cost: unit_cut_cost, // back-compat alias
    unit_paint_cost,
    unit_total_cost,
    // Row-level totals (so caller can compare with stand-alone estimator numbers)
    row_total_material_cost: unit_material_cost * numLetters,
    row_total_cut_cost: totalCutCost,
    row_total_paint_mask_cost: totalPaintMaskCost,
    row_total_paint_supplies_cost: totalLiquidPaintAndSuppliesCost,
    row_total_paint_labor_cost: totalPaintLaborCost,
    row_total_paint_gallons: totalPaintGallons,
    row_machine_time_hours: machineTimeHours,
    row_setup_time_hours: setupTimeHours,
  };
};

// Resolve cost_per_sqin from a material record (taking yield into account)
export const materialCostPerSqin = (material) => {
  if (!material) return 0;
  const sheetArea = num(material.sheet_length_inches) * num(material.sheet_width_inches);
  const yieldFactor = Math.max(0.05, Math.min(1, num(material.yield_factor, 0.7)));
  const usableArea = sheetArea * yieldFactor;
  if (usableArea <= 0) return 0;
  return num(material.cost_per_sheet) / usableArea;
};

// Look up the per-thickness cut speed setting for the active method.
//   CNC:   cnc_cut_speed_<thickness>
//   Laser: cut_speed_<thickness>
export const lookupCutSpeed = (cuttingMethod, thicknessInches, settings) => {
  if (!thicknessInches) return null;
  const candidates = decimalToImperialKeys(thicknessInches);
  const prefix = cuttingMethod === "laser" ? "cut_speed_" : "cnc_cut_speed_";
  for (const c of candidates) {
    const v = settings[`${prefix}${c}`];
    if (v !== undefined && v !== null && v !== "") return num(v);
  }
  return null;
};

// Lookup material cut multiplier from settings.
//   CNC: <material>_cnc_cut_multiplier
//   Laser: <material>_cut_multiplier
export const lookupCutMultiplier = (cuttingMethod, materialType, settings) => {
  if (!materialType) return 1;
  const mat = materialType.toLowerCase();
  const key = cuttingMethod === "laser" ? `${mat}_cut_multiplier` : `${mat}_cnc_cut_multiplier`;
  const v = settings[key];
  return v !== undefined && v !== null && v !== "" ? num(v, 1) : 1;
};

// Map common decimal thicknesses → key strings used in settings.
const decimalToImperialKeys = (decimal) => {
  const map = {
    0.0625: ["1_16"],
    0.125: ["1_8"],
    0.1875: ["3_16"],
    0.25: ["1_4"],
    0.375: ["3_8"],
    0.5: ["1_2"],
    0.625: ["5_8"],
    0.75: ["3_4"],
    0.875: ["7_8"],
    1: ["1"],
    1.25: ["1_1_4"],
    1.5: ["1_1_2"],
    2: ["2"],
    2.5: ["2_1_2"],
    3: ["3"],
    3.5: ["3_1_2"],
    4: ["4"],
  };
  const snap = Math.round(decimal * 16) / 16;
  return map[snap] || [];
};

export const PAINT_SIDES_LABELS = {
  none: "No Paint",
  front: "Front Only",
  front_and_edges: "Front + Edges",
  all: "All Sides",
};

export const CUTTING_METHOD_LABELS = {
  cnc: "CNC Routing",
  laser: "Laser Cutting",
};

// Logic for suggesting equipment based on project line items.
// Pure functions — no React, no entity calls.

// Equipment types that lift workers to a height (used to match install height)
const LIFT_TYPES = ["ladder", "scissor_lift", "boom_lift", "boom_truck", "scaffold"];
const BOOM_TYPES = ["boom_lift", "boom_truck"];

// Vehicles needed to transport crew & gear to the site
const VEHICLE_TYPES = ["truck", "van", "flatbed", "boom_truck"];

// Owned equipment never carries a delivery / pickup fee (it's your own gear).
export function isOwnedEquipment(invOrRow = {}) {
  if (invOrRow.ownership) return invOrRow.ownership === "owned";
  return invOrRow.pricing_mode === "owned_flat" || invOrRow.pricing_mode === "per_project_flat";
}

// Is this inventory record owned (vs rented)?
const invIsOwned = (e) =>
  e.ownership === "owned" || e.pricing_mode === "owned_flat" || e.pricing_mode === "per_project_flat";

const safetyMarginOf = (e) => {
  const m = parseFloat(e.vertical_reach_safety_margin_feet);
  return isNaN(m) ? 2 : m;
};

// Does this lift reach the install height (with its safety margin)?
const liftReaches = (e, height) =>
  (parseFloat(e.max_height_feet) || 0) >= height + safetyMarginOf(e);

/**
 * Pick exactly ONE lift for the job. Selection order:
 *  1. A boom flagged `is_primary_owned` (your go-to owned boom) — used whenever
 *     it can reach the install height. This is the "normal use" default.
 *  2. A boom flagged `is_default_for_height` whose configured range contains
 *     the install height.
 *  3. Otherwise the SMALLEST lift that reaches the height — but OWNED lifts are
 *     always preferred over rented ones when both can reach. Only fall back to
 *     a rented lift when no owned lift is tall enough (install height exceeds
 *     your owned reach).
 * Never returns more than one lift.
 */
function pickLift(active, maxHeight) {
  const lifts = active.filter((e) => LIFT_TYPES.includes(e.equipment_type));
  if (lifts.length === 0) return null;

  // 1) Primary owned boom — your marked go-to, used whenever it reaches.
  const primaryOwned = lifts.find(
    (e) => invIsOwned(e) && e.is_primary_owned && liftReaches(e, maxHeight)
  );
  if (primaryOwned) return primaryOwned;

  // 2) Default-by-height-range boom.
  const defaultByRange = lifts.find((e) => {
    if (!BOOM_TYPES.includes(e.equipment_type)) return false;
    if (!e.is_default_for_height) return false;
    const min = parseFloat(e.default_height_min_feet) || 0;
    const max = parseFloat(e.default_height_max_feet) || 0;
    if (max <= 0) return false;
    return maxHeight >= min && maxHeight <= max;
  });
  if (defaultByRange) return defaultByRange;

  const bySize = (a, b) => (parseFloat(a.max_height_feet) || 0) - (parseFloat(b.max_height_feet) || 0);

  // 3a) Smallest OWNED lift that reaches (owned always preferred).
  const ownedReaching = lifts.filter((e) => invIsOwned(e) && liftReaches(e, maxHeight)).sort(bySize);
  if (ownedReaching.length > 0) return ownedReaching[0];

  // 3b) Install height exceeds owned reach → smallest RENTED lift that reaches.
  const rentedReaching = lifts.filter((e) => !invIsOwned(e) && liftReaches(e, maxHeight)).sort(bySize);
  if (rentedReaching.length > 0) return rentedReaching[0];

  // 3c) Nothing clears the safety margin — pick the tallest lift that at least
  //     physically reaches, preferring owned.
  const anyReaching = lifts
    .filter((e) => (parseFloat(e.max_height_feet) || 0) >= maxHeight)
    .sort((a, b) => {
      const own = (invIsOwned(b) ? 1 : 0) - (invIsOwned(a) ? 1 : 0);
      if (own !== 0) return own;
      return bySize(b, a); // tallest first
    });
  return anyReaching[0] || null;
}

/**
 * Given a list of line items and the equipment inventory, suggest which
 * pieces of equipment should be selected. Returns inventory items.
 * Always returns at most ONE lift + (if needed) ONE transport vehicle.
 */
export function suggestEquipmentForProject(items = [], inventory = []) {
  if (!items.length || !inventory.length) return [];

  const maxHeight = items.reduce(
    (m, it) => Math.max(m, parseFloat(it.installation_height_feet) || 0),
    0
  );

  const active = inventory.filter((e) => e.is_active !== false);
  const suggestions = [];

  // Exactly one lift for the job.
  const lift = pickLift(active, maxHeight);
  if (lift) suggestions.push(lift);

  // Add a transport vehicle (prefer owned) — unless the lift IS a vehicle (boom truck).
  const haveVehicle = suggestions.some((s) => VEHICLE_TYPES.includes(s.equipment_type));
  if (!haveVehicle) {
    const vehicles = active
      .filter((e) => VEHICLE_TYPES.includes(e.equipment_type))
      .sort((a, b) => (invIsOwned(a) ? 0 : 1) - (invIsOwned(b) ? 0 : 1));
    if (vehicles.length > 0) suggestions.push(vehicles[0]);
  }

  return suggestions;
}

/**
 * Build a `selected_equipment` row from an inventory equipment record.
 * Default duration = ON-SITE clock time (labor hours ÷ crew size) mapped to the
 * pricing mode — a 3-person crew burns 24 labor-hours in 8 site hours, so the
 * lift is only rented for 1 day, not 3.
 * For booms, seeds `idle_running_cost_per_hour` and `idle_hours` (defaults to labor hours).
 */
export function selectedEquipmentFromInventory(inv, projectLaborHours = 0, crewSize = 1) {
  const laborHours = parseFloat(projectLaborHours) || 0;
  // Equipment is rented for ON-SITE (clock) time, not man-hours.
  const crew = Math.max(1, parseInt(crewSize) || 1);
  const clockHours = laborHours / crew;
  const clockDays = Math.max(1, Math.ceil(clockHours / 8));

  let duration = 1;
  let unitCost = 0;

  switch (inv.pricing_mode) {
    case "per_hour":
      duration = Math.max(1, Math.ceil(clockHours));
      unitCost = parseFloat(inv.cost_per_hour) || 0;
      break;
    case "per_day":
      duration = clockDays;
      unitCost = parseFloat(inv.cost_per_day) || 0;
      break;
    case "per_week":
      duration = Math.max(1, Math.ceil(clockDays / 5));
      unitCost = parseFloat(inv.cost_per_week) || 0;
      break;
    case "per_month":
      duration = 1;
      unitCost = parseFloat(inv.cost_per_month) || 0;
      break;
    case "owned_flat":
    case "per_project_flat":
      duration = 1;
      unitCost = parseFloat(inv.cost_flat) || 0;
      break;
    default:
      duration = 1;
      unitCost = 0;
  }

  // Idle-running fields apply to booms only
  const isBoom = BOOM_TYPES.includes(inv.equipment_type);
  const idleRate = isBoom ? (parseFloat(inv.idle_running_cost_per_hour) || 0) : 0;
  // Default idle to on-site clock hours rounded up — most installs run the boom continuously
  const idleHours = isBoom && idleRate > 0 ? Math.max(0, Math.ceil(clockHours)) : 0;

  // Owned equipment never has a delivery / pickup fee.
  const owned = isOwnedEquipment(inv);

  return {
    equipment_id: inv.id,
    inventory_entity: inv._inventory_entity || inv.inventory_entity || "",
    equipment_name: inv.equipment_name,
    equipment_type: inv.equipment_type,
    pricing_mode: inv.pricing_mode,
    ownership: owned ? "owned" : (inv.ownership || "rented"),
    duration,
    include_delivery: false,
    delivery_pickup_cost: owned ? 0 : (parseFloat(inv.delivery_pickup_cost) || 0),
    unit_cost: unitCost,
    idle_running_cost_per_hour: idleRate,
    idle_hours: idleHours,
    idle_cost: idleRate * idleHours,
    total_cost: unitCost * duration + (idleRate * idleHours),
    notes: "",
  };
}

/**
 * Recalculate the total cost of a selected equipment row.
 */
export function recalcEquipmentRow(row) {
  const duration = parseFloat(row.duration) || 0;
  const unitCost = parseFloat(row.unit_cost) || 0;
  // Owned equipment never bills a delivery / pickup fee.
  const delivery = (!isOwnedEquipment(row) && row.include_delivery)
    ? parseFloat(row.delivery_pickup_cost) || 0
    : 0;
  const idleHours = parseFloat(row.idle_hours) || 0;
  const idleRate = parseFloat(row.idle_running_cost_per_hour) || 0;
  const idle_cost = idleHours * idleRate;
  return {
    ...row,
    idle_cost,
    total_cost: unitCost * duration + delivery + idle_cost,
  };
}

/**
 * Recalculate a personnel row's total cost.
 */
export function recalcPersonnelRow(row) {
  const rate = parseFloat(row.hourly_rate) || 0;
  const hours = parseFloat(row.hours) || 0;
  return { ...row, total_cost: rate * hours };
}

/**
 * Display label for a pricing mode's duration unit.
 */
export function durationUnitLabel(pricing_mode) {
  switch (pricing_mode) {
    case "per_hour": return "hours";
    case "per_day": return "days";
    case "per_week": return "weeks";
    case "per_month": return "months";
    case "owned_flat":
    case "per_project_flat":
      return "flat";
    default: return "units";
  }
}

/**
 * Suggested crew size for a project:
 *   - 3 people when max install height >= 40 ft OR 30+ total letters
 *   - otherwise 2 (Crew Lead + Installer)
 * Shared by the personnel suggester AND the equipment duration math so
 * on-site time assumptions stay consistent.
 */
export function suggestCrewSize(items = []) {
  const maxHeight = items.reduce(
    (m, it) => Math.max(m, parseFloat(it.installation_height_feet) || 0),
    0
  );
  const totalLetters = items.reduce(
    (s, it) => s + (parseFloat(it.qty_letters) || 0),
    0
  );
  return (maxHeight >= 40 || totalLetters >= 30) ? 3 : 2;
}

/**
 * Suggest an appropriate crew (Crew Lead / Installer / Helper) for a project.
 * Crew size comes from suggestCrewSize(); total crew hours = project labor
 * hours, divided evenly per person.
 */
export function suggestPersonnelForProject(items = [], projectLaborHours = 0, rateForRole = () => 0) {
  const crewSize = suggestCrewSize(items);

  const perPersonHours = projectLaborHours && crewSize > 0
    ? +(projectLaborHours / crewSize).toFixed(2)
    : 0;

  const roles = ["Crew Lead", "Installer", "Helper"];
  return Array.from({ length: crewSize }, (_, i) => {
    const role = roles[i] || "Installer";
    return recalcPersonnelRow({
      name: "",
      role,
      hourly_rate: rateForRole(role),
      hours: perPersonHours,
      total_cost: 0,
    });
  });
}

// Calculation logic for Channel Letter Installation estimates
// Pure functions — no React, no entity calls.

import { getWallMaterialMultiplier } from "./wallMaterials";
import { heightBucketFor, normalizeEnv, resolveRateMinutes, TYPE_PREFIXES } from "./installSizeRates";

export const TYPE_LABELS = {
  flush_mount: "Flush Mount",
  halo_lit: "Halo-Lit",
  raceway: "Raceway",
  dimensional_lettering: "Dimensional Lettering",
  dimensional_lettering_with_backer: "Dimensional Lettering + Backer",
};

export const SIZE_LABELS = {
  extra_small: 'XS (2"-8")',
  small: 'Small (8"-12")',
  medium: 'Medium (12"-24")',
  large: 'Large (24"-48")',
  extra_large: 'XL (48"-60")',
  extra_extra_large: 'XXL (60"+)',
};

export const emptyLineItem = () => ({
  description: "",
  installation_type: "flush_mount",
  qty_letters: 10,
  letter_size: "medium",
  letter_height_inches: 24,
  installation_height_feet: 12,
  raceway_length_feet: 0,
  wall_material: "eifs",
  thick_hollow_walls: false,
  parapet: false,
  parapet_electrical_routing: "roof",
  poor_electrical_access: false,
  poor_electrical_severity: 1,
  escort_required: false,
  badging_checkin: false,
  after_hours_weekend: false,
  set_hours_installation: false,
  poor_site_access: false,
  poor_site_access_severity: 1,
  materials: [],
});

// Decide which inventory items should auto-attach to a new line item.
// NOTE: Raceway hardware ("per_raceway_foot") is intentionally EXCLUDED here —
// raceway cost is priced exclusively on the Letters tab, never in install materials.
export const defaultMaterialsForItem = (item, inventory) => {
  return (inventory || [])
    .filter(inv => {
      if (!inv.is_default) return false;
      if (inv.pricing_mode === "per_raceway_foot") return false; // raceway priced on Letters tab only
      // Prefer the new multi-select field; fall back to legacy single-value field.
      const list = Array.isArray(inv.applies_to_list) ? inv.applies_to_list : [];
      if (list.length > 0) return list.includes(item.installation_type);
      if (!inv.applies_to || inv.applies_to === "all") return true;
      return inv.applies_to === item.installation_type;
    })
    .map(inv => materialFromInventory(inv, item));
};

// Build a material line from an inventory record + line item context
export const materialFromInventory = (inv, item) => {
  const m = {
    inventory_item_id: inv.id,
    item_name: inv.item_name,
    pricing_mode: inv.pricing_mode,
    unit_cost: 0,
    quantity: 0,
    total_cost: 0,
  };

  if (inv.pricing_mode === "per_letter_flat") {
    m.unit_cost = parseFloat(inv.cost_per_letter) || 0;
    m.quantity = parseFloat(item.qty_letters) || 0;
  } else if (inv.pricing_mode === "per_letter_by_size") {
    const sizeKey = `cost_${item.letter_size}`;
    m.unit_cost = parseFloat(inv[sizeKey]) || 0;
    m.quantity = parseFloat(item.qty_letters) || 0;
  } else if (inv.pricing_mode === "per_raceway_foot") {
    m.unit_cost = parseFloat(inv.cost_per_foot) || 0;
    m.quantity = parseFloat(item.raceway_length_feet) || 0;
  } else if (inv.pricing_mode === "per_project_flat") {
    m.unit_cost = parseFloat(inv.cost_flat) || 0;
    m.quantity = 1;
  }

  m.total_cost = m.unit_cost * m.quantity;
  return m;
};

// Re-cost a single line item: labor hours, labor cost, materials, total
export const calcLineItem = (item, settings, inventory) => {
  const laborRate = parseFloat(settings.install_labor_rate) || 65;

  // Base rates are stored in MINUTES — convert to hours when reading.
  // Each installation type has its own set of size-based times.
  const MIN_TO_HR = 1 / 60;

  // Defaults by type and size: [drill, prep, electrical]
  const TYPE_DEFAULTS = {
    flush_mount: {
      extra_small: [15, 30, 5],
      small: [30, 60, 10],
      medium: [50, 100, 15],
      large: [80, 160, 20],
      extra_large: [120, 240, 25],
      extra_extra_large: [170, 340, 30],
    },
    halo_lit: {
      extra_small: [15, 30, 5],
      small: [30, 60, 10],
      medium: [50, 100, 15],
      large: [80, 160, 20],
      extra_large: [120, 240, 25],
      extra_extra_large: [170, 340, 30],
    },
    dimensional_lettering: {
      extra_small: [10, 20, 0],
      small: [20, 45, 0],
      medium: [40, 80, 0],
      large: [65, 130, 0],
      extra_large: [100, 200, 0],
      extra_extra_large: [140, 280, 0],
    },
  };

  // Resolve env + height bucket for this line item.
  // Per-item env wins; otherwise the project-level env is passed in via settings._project_install_environment.
  const env = normalizeEnv(item.install_environment || settings._project_install_environment || "exterior");
  const heightBucket = heightBucketFor(item.installation_height_feet);

  const sizeMinutesForType = (type, size) => {
    const prefixes = TYPE_PREFIXES[type];
    const defs = TYPE_DEFAULTS[type]?.[size] || [50, 100, 15];
    if (!prefixes) return defs[0] + defs[1] + defs[2];
    const d = resolveRateMinutes(settings, prefixes.drill, size, env, heightBucket, defs[0]);
    const p = resolveRateMinutes(settings, prefixes.prep,  size, env, heightBucket, defs[1]);
    const e = prefixes.elec ? resolveRateMinutes(settings, prefixes.elec, size, env, heightBucket, defs[2]) : 0;
    return d + p + e;
  };

  // The "+ backer" variant installs at the same per-size rates as plain
  // dimensional lettering (no electrical). Normalize for rate lookups —
  // previously it fell through to medium flush-mount defaults for every size.
  const rateType = item.installation_type === "dimensional_lettering_with_backer"
    ? "dimensional_lettering"
    : item.installation_type;

  let baseHours = 0;

  if (rateType === "raceway") {
    // Raceway: base + extra minutes per foot, plus per-letter mounting minutes, plus electrical hookup per raceway line item.
    const basePerFt = (parseFloat(settings.install_raceway_base_minutes_per_foot) || 30) * MIN_TO_HR;
    const extraPerFt = (parseFloat(settings.install_raceway_extra_minutes_per_foot) || 0) * MIN_TO_HR;
    const racewayHoursPerFoot = basePerFt + extraPerFt;
    baseHours = (parseFloat(item.raceway_length_feet) || 0) * racewayHoursPerFoot;
    const letterMountingHours = (parseFloat(settings.install_raceway_letter_mounting_rate) || 18) * MIN_TO_HR;
    baseHours += (parseFloat(item.qty_letters) || 0) * letterMountingHours;
    const racewayElecHours = (parseFloat(settings.install_raceway_electrical_hookup_minutes) || 30) * MIN_TO_HR;
    baseHours += racewayElecHours;
  } else {
    const minutesPerLetter = sizeMinutesForType(rateType, item.letter_size);
    baseHours = (parseFloat(item.qty_letters) || 0) * minutesPerLetter * MIN_TO_HR;
  }

  // Thick / Hollow Walls — ADDITIVE minutes (per letter and per raceway).
  // Added to baseHours so it still scales with height & wall-material multipliers below.
  if (item.thick_hollow_walls) {
    const extraPerLetterMin = parseFloat(settings.install_thick_walls_extra_per_letter);
    const extraPerRacewayMin = parseFloat(settings.install_thick_walls_extra_per_raceway);
    const perLetter = isNaN(extraPerLetterMin) ? 8 : extraPerLetterMin;
    const perRaceway = isNaN(extraPerRacewayMin) ? 30 : extraPerRacewayMin;
    baseHours += (parseFloat(item.qty_letters) || 0) * perLetter * MIN_TO_HR;
    if (item.installation_type === "raceway") {
      baseHours += perRaceway * MIN_TO_HR;
    }
  }

  // Parapet — ADDITIVE minutes (per letter and per raceway). Two routing options:
  //   - "roof"  : electrical runs along the rooftop (easier)
  //   - "drop"  : electrical drops down inside the parapet cavity (harder — fishing power down)
  // Defaults to "roof" if not specified.
  if (item.parapet) {
    const routing = item.parapet_electrical_routing === "drop" ? "drop" : "roof";
    const perLetterKey = routing === "drop" ? "install_parapet_drop_extra_per_letter" : "install_parapet_roof_extra_per_letter";
    const perRacewayKey = routing === "drop" ? "install_parapet_drop_extra_per_raceway" : "install_parapet_roof_extra_per_raceway";
    const perLetterDefault = routing === "drop" ? 18 : 10;
    const perRacewayDefault = routing === "drop" ? 65 : 40;
    const extraPerLetterMin = parseFloat(settings[perLetterKey]);
    const extraPerRacewayMin = parseFloat(settings[perRacewayKey]);
    const perLetter = isNaN(extraPerLetterMin) ? perLetterDefault : extraPerLetterMin;
    const perRaceway = isNaN(extraPerRacewayMin) ? perRacewayDefault : extraPerRacewayMin;
    baseHours += (parseFloat(item.qty_letters) || 0) * perLetter * MIN_TO_HR;
    if (item.installation_type === "raceway") {
      baseHours += perRaceway * MIN_TO_HR;
    }
  }

  // NOTE: A separate "height multiplier" used to be applied here. Heights are now
  // baked into each per-size rate set (size × height bucket × interior/exterior),
  // so no extra multiplier is needed.

  // Wall material multiplier
  baseHours *= getWallMaterialMultiplier(item.wall_material, settings);

  if (item.escort_required) baseHours *= parseFloat(settings.install_escort_multiplier) || 1.15;
  if (item.badging_checkin) baseHours *= parseFloat(settings.install_badging_multiplier) || 1.1;
  if (item.after_hours_weekend) baseHours *= parseFloat(settings.install_after_hours_multiplier) || 1.5;
  if (item.set_hours_installation) baseHours *= parseFloat(settings.install_set_hours_multiplier) || 1.15;

  // Poor Site Access — ADDITIVE: severity level adds minutes/letter on top of the base install time.
  if (item.poor_site_access) {
    const level = Math.max(1, Math.min(10, parseInt(item.poor_site_access_severity) || 1));
    const severityDefaults = { 1: 3, 2: 6, 3: 10, 4: 15, 5: 20, 6: 28, 7: 38, 8: 50, 9: 65, 10: 90 };
    const bonusMin = parseFloat(settings[`install_site_access_level_${level}`]);
    const bonus = isNaN(bonusMin) ? severityDefaults[level] : bonusMin;
    baseHours += ((parseFloat(item.qty_letters) || 0) * bonus) * MIN_TO_HR;
  }

  // Poor Electrical Access — ADDITIVE: severity level adds minutes/letter on top of the size's electrical hookup baseline.
  // Note: the size's electrical hookup baseline is ALREADY included in baseHours via sizeMinutesForType() above.
  // Here we add only the SEVERITY bonus on top of that, scaled by qty_letters.
  // Excluded for raceway (uses its own per-raceway hookup) and dimensional (no electrical at all).
  if (item.poor_electrical_access && rateType !== "raceway" && rateType !== "dimensional_lettering") {
    const level = Math.max(1, Math.min(10, parseInt(item.poor_electrical_severity) || 1));
    const severityDefaults = { 1: 3, 2: 6, 3: 10, 4: 15, 5: 20, 6: 28, 7: 38, 8: 50, 9: 65, 10: 90 };
    const bonusMin = parseFloat(settings[`install_poor_electrical_level_${level}`]);
    const bonus = isNaN(bonusMin) ? severityDefaults[level] : bonusMin;
    baseHours += ((parseFloat(item.qty_letters) || 0) * bonus) * MIN_TO_HR;
  }

  // Recompute material quantities based on current item state (qty/size/raceway changed).
  // Raceway hardware ("per_raceway_foot") is priced on the Letters tab only, so we
  // strip any such material that may linger on older saved estimates.
  const materials = (item.materials || [])
    .filter(mat => mat.pricing_mode !== "per_raceway_foot")
    .map(mat => {
      const inv = (inventory || []).find(i => i.id === mat.inventory_item_id);
      if (!inv) {
        // detached/manual material — leave as-is
        return { ...mat, total_cost: (parseFloat(mat.unit_cost) || 0) * (parseFloat(mat.quantity) || 0) };
      }
      if (inv.pricing_mode === "per_raceway_foot") return null;
      return materialFromInventory(inv, item);
    })
    .filter(Boolean);

  const materialsCost = materials.reduce((sum, m) => sum + (parseFloat(m.total_cost) || 0), 0);
  const laborCost = baseHours * laborRate;
  const itemTotalCost = laborCost + materialsCost;

  return {
    ...item,
    materials,
    labor_hours: baseHours,
    labor_cost: laborCost,
    materials_cost: materialsCost,
    item_total_cost: itemTotalCost,
  };
};

// Project-level rollup
export const calcProjectTotals = (project) => {
  const items = project.items || [];
  const total_materials_cost = items.reduce((s, it) => s + (parseFloat(it.materials_cost) || 0), 0);
  const labor_cost = items.reduce((s, it) => s + (parseFloat(it.labor_cost) || 0), 0);
  const labor_hours = items.reduce((s, it) => s + (parseFloat(it.labor_hours) || 0), 0);

  // Equipment rollup
  const total_equipment_cost = (project.selected_equipment || []).reduce(
    (s, e) => s + (parseFloat(e.total_cost) || 0), 0
  );

  // Personnel rollup
  const total_personnel_cost = (project.personnel || []).reduce(
    (s, p) => s + (parseFloat(p.total_cost) || 0), 0
  );

  // When a crew is assigned, the personnel rows ARE the priced version of the
  // calculated install hours (same hours split across the crew at role rates).
  // Counting both would bill the same labor twice — personnel pricing REPLACES
  // the flat-rate labor estimate in the subtotal.
  const labor_priced_via_personnel = total_personnel_cost > 0;
  const labor_cost_in_subtotal = labor_priced_via_personnel ? 0 : labor_cost;

  // Letters purchase rollup (calculated by lettersCalculator separately;
  // we just read the already-stored project.total_letters_cost here)
  const total_letters_cost = parseFloat(project.total_letters_cost) || 0;

  // Supplies are derived from materials cost (percent) + an optional manual extra amount
  const pct = parseFloat(project.supplies_percent_of_materials);
  const suppliesPct = isNaN(pct) ? 10 : pct; // default 10% of materials
  const extra = parseFloat(project.extra_supplies_cost) || 0;
  const supplies_from_materials = total_materials_cost * (suppliesPct / 100);
  const total_supplies_cost = supplies_from_materials + extra;

  // Travel cost — already computed in the UI and stored on the project. Just roll it in.
  const total_travel_cost = parseFloat(project.total_travel_cost) || 0;

  const subtotal =
    labor_cost_in_subtotal +
    total_materials_cost +
    total_supplies_cost +
    total_equipment_cost +
    total_personnel_cost +
    total_travel_cost +
    total_letters_cost;
  const markupPct = parseFloat(project.markup_percent) || 0;
  const markup_amount = subtotal * (markupPct / 100);
  const total_cost = subtotal + markup_amount;

  return {
    labor_hours,
    labor_cost,
    labor_cost_in_subtotal,
    labor_priced_via_personnel,
    total_materials_cost,
    total_supplies_cost,
    total_equipment_cost,
    total_personnel_cost,
    total_travel_cost,
    subtotal,
    markup_amount,
    total_cost,
  };
};

// Export helpers for Channel Letter Installation estimates
import { TYPE_LABELS, SIZE_LABELS } from "./installCalculator";

const fmt = (v) => `$${(parseFloat(v) || 0).toFixed(2)}`;

export const buildSummaryText = (project) => {
  const lines = [];
  lines.push(`CHANNEL LETTER INSTALLATION ESTIMATE`);
  lines.push(`================================`);
  lines.push(`Project: ${project.project_name || "-"}`);
  lines.push(`Client:  ${project.client_name || "-"}`);
  lines.push(`Est #:   ${project.estimate_number || "-"}`);
  if (project.hyperlink) lines.push(`Link:    ${project.hyperlink}`);
  lines.push("");
  lines.push(`LINE ITEMS`);
  lines.push(`----------`);
  (project.items || []).forEach((it, i) => {
    const label = it.description || TYPE_LABELS[it.installation_type] || "Item";
    lines.push(`${i + 1}. ${label} — ${TYPE_LABELS[it.installation_type] || it.installation_type}`);
    if (it.installation_type === "raceway") {
      lines.push(`   Raceway: ${it.raceway_length_feet} ft · ${it.qty_letters} letters`);
    } else {
      lines.push(`   ${it.qty_letters} letters · ${SIZE_LABELS[it.letter_size] || it.letter_size}`);
    }
    lines.push(`   Height: ${it.installation_height_feet} ft`);
    const conds = [];
    if (it.thick_hollow_walls) conds.push("Thick/Hollow Walls");
    if (it.parapet) conds.push("Parapet");
    if (it.poor_electrical_access) conds.push("Poor Electrical");
    if (conds.length) lines.push(`   Conditions: ${conds.join(", ")}`);
    lines.push(`   Labor: ${(it.labor_hours || 0).toFixed(2)} hrs (${fmt(it.labor_cost)})`);
    lines.push(`   Materials: ${fmt(it.materials_cost)}`);
    lines.push(`   Item Total: ${fmt(it.item_total_cost)}`);
    lines.push("");
  });
  lines.push(`TOTALS`);
  lines.push(`------`);
  lines.push(`Labor:        ${fmt(project.labor_cost)} (${(project.labor_hours || 0).toFixed(2)} hrs)`);
  lines.push(`Materials:    ${fmt(project.total_materials_cost)}`);
  lines.push(`Supplies:     ${fmt(project.total_supplies_cost)}`);
  lines.push(`Subtotal:     ${fmt(project.subtotal)}`);
  if ((project.markup_percent || 0) > 0) {
    lines.push(`Markup (${project.markup_percent}%): ${fmt(project.markup_amount)}`);
  }
  lines.push(`TOTAL:        ${fmt(project.total_cost)}`);
  if (project.notes) {
    lines.push("");
    lines.push(`Notes: ${project.notes}`);
  }
  return lines.join("\n");
};

export const downloadCSV = (project) => {
  const rows = [["#", "Description", "Type", "Qty Letters", "Size", "Raceway Ft", "Height Ft", "Labor Hrs", "Labor $", "Materials $", "Item Total $"]];
  (project.items || []).forEach((it, i) => {
    rows.push([
      i + 1,
      it.description || "",
      TYPE_LABELS[it.installation_type] || it.installation_type,
      it.qty_letters || 0,
      SIZE_LABELS[it.letter_size] || it.letter_size || "",
      it.raceway_length_feet || 0,
      it.installation_height_feet || 0,
      (it.labor_hours || 0).toFixed(2),
      (it.labor_cost || 0).toFixed(2),
      (it.materials_cost || 0).toFixed(2),
      (it.item_total_cost || 0).toFixed(2),
    ]);
  });
  rows.push([]);
  rows.push(["", "", "", "", "", "", "", "Labor Total", (project.labor_cost || 0).toFixed(2), "Materials", (project.total_materials_cost || 0).toFixed(2)]);
  rows.push(["", "", "", "", "", "", "", "Supplies", (project.total_supplies_cost || 0).toFixed(2), "Subtotal", (project.subtotal || 0).toFixed(2)]);
  if ((project.markup_percent || 0) > 0) {
    rows.push(["", "", "", "", "", "", "", `Markup ${project.markup_percent}%`, (project.markup_amount || 0).toFixed(2), "", ""]);
  }
  rows.push(["", "", "", "", "", "", "", "TOTAL", (project.total_cost || 0).toFixed(2), "", ""]);

  const csv = rows.map(r => r.map(cell => {
    const s = String(cell ?? "");
    return s.includes(",") || s.includes('"') ? `"${s.replace(/"/g, '""')}"` : s;
  }).join(",")).join("\n");

  const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = `${(project.project_name || "estimate").replace(/[^a-z0-9]/gi, "_")}.csv`;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
};

// Centralized helper for size × height × environment installation-time settings.
//
// We resolve install times along three axes:
//   - size (extra_small … extra_extra_large)
//   - height bucket (h0_12, h12_20, h20_30, h30plus)
//   - environment (interior, exterior)
//
// Each (type × size × height × env) combination has its own drill / prep /
// electrical setting. Backward compatibility: when a new combo-keyed setting
// is missing, we fall back to the legacy size-only key (e.g.
// install_drill_rate_medium) so existing apps keep working.

export const SIZE_KEYS = [
  "extra_small",
  "small",
  "medium",
  "large",
  "extra_large",
  "extra_extra_large",
];

export const HEIGHT_BUCKETS = [
  { key: "h0_12",    label: "0–12 ft",  min: 0,  max: 12 },
  { key: "h12_20",   label: "12–20 ft", min: 12, max: 20 },
  { key: "h20_30",   label: "20–30 ft", min: 20, max: 30 },
  { key: "h30plus",  label: "30+ ft",   min: 30, max: Infinity },
];

export const ENV_KEYS = ["interior", "exterior"];

export const heightBucketFor = (heightFt) => {
  const h = parseFloat(heightFt) || 0;
  if (h <= 12) return "h0_12";
  if (h <= 20) return "h12_20";
  if (h <= 30) return "h20_30";
  return "h30plus";
};

export const normalizeEnv = (env) => (env === "interior" ? "interior" : "exterior");

// Settings-key prefixes by installation type (drill / prep / elec)
// These match the legacy size-only key prefixes — we just append the
// environment + height suffix when looking up the new keys.
export const TYPE_PREFIXES = {
  flush_mount:           { drill: "install_drill_rate_",             prep: "install_prep_rate_",             elec: "install_electrical_rate_" },
  halo_lit:              { drill: "install_halo_drill_rate_",        prep: "install_halo_prep_rate_",        elec: "install_halo_electrical_rate_" },
  dimensional_lettering: { drill: "install_dimensional_drill_rate_", prep: "install_dimensional_prep_rate_", elec: null },
};

// Build the env-and-height-qualified setting key, e.g.
//   install_drill_rate_medium__exterior__h12_20
export const qualifiedKey = (prefix, size, env, heightBucket) =>
  `${prefix}${size}__${normalizeEnv(env)}__${heightBucket}`;

// Resolve a single setting value, falling back to the legacy size-only key
// if the qualified key isn't set yet.
export const resolveRateMinutes = (settings, prefix, size, env, heightBucket, fallbackDefault = 0) => {
  if (!prefix) return 0;
  const qk = qualifiedKey(prefix, size, env, heightBucket);
  const qv = parseFloat(settings[qk]);
  if (!isNaN(qv)) return qv;
  // Legacy fallback: same setting key without env/height qualifiers.
  const legacy = parseFloat(settings[`${prefix}${size}`]);
  if (!isNaN(legacy)) return legacy;
  return fallbackDefault;
};

// Notes use the same suffix conventions, with __notes appended.
export const qualifiedNotesKey = (prefix, size, env, heightBucket) =>
  `${qualifiedKey(prefix, size, env, heightBucket)}__notes`;

// Estimates the average letter width (in inches) for a given letter height,
// based on the average advance widths of 10 common signage fonts.
//
// The factor below is the simple average of the lowercase "x" width / cap-height
// for these 10 fonts (uppercase set, since signage typically uses caps):
//   Helvetica, Arial, Futura, Gotham, Univers, Avenir, Frutiger, Trade Gothic,
//   Myriad, Optima.
// Average advance-width / cap-height ratio across the alphabet (A–Z) ≈ 0.72.
// Rounding UP to the next half-inch to match shop practice when ordering
// stock material.
//
// Returns a number in inches (>= 0). Returns 0 for non-positive heights.

export const AVG_WIDTH_TO_HEIGHT_RATIO = 0.72;

/**
 * Auto-estimate the average letter width for a given height.
 * Result is rounded UP to the nearest 0.5".
 */
export const estimateAverageLetterWidth = (heightInches) => {
  const h = parseFloat(heightInches);
  if (!isFinite(h) || h <= 0) return 0;
  const raw = h * AVG_WIDTH_TO_HEIGHT_RATIO;
  // Round up to the next 0.5"
  return Math.ceil(raw * 2) / 2;
};

