  const flagged = hasIssueFor(issues, field)
    || (value && issues.some(i => i.inventoryId === value));
  return (
  <div className={`p-3 rounded-lg border ${apply ? accent : "bg-slate-50 border-slate-200 opacity-70"}`}>
