              className={`py-2 text-xs rounded-lg transition-all data-[state=active]:text-white data-[state=active]:shadow-md ${SIGN_TYPE_ACTIVE_BG[st.color] || SIGN_TYPE_ACTIVE_BG.slate}`}
            >
